/** All translations for zizhitongjian ch.051 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑第051卷", literal: "Zizhi Tongjian, Volume 51.", idiomatic: "Zizhi Tongjian, Volume 51." },
  { zh: "【漢紀四十三】起旃蒙赤奮若，盡昭陽作噩，凡九年。", literal: "【Han Records 43】 From Zhanmeng Chifenruo through Zhaoyang Zuo'e—in all, nine years.", idiomatic: "【Han Records 43】 From the first year of the Zhanmeng cycle through the last year of the Zhaoyang cycle—nine years in all." },
  { zh: "春，二月，乙亥，下邳惠王衍薨。", literal: "In spring, the second month, on the day yihai, Prince Hui of Xiapi Yan died.", idiomatic: "In spring, in the second month, on yihai day, Prince Hui of Xiapi Yan died." },
  { zh: "甲辰，車駕南巡。", literal: "On the day jiachen, the imperial carriage made a southern tour.", idiomatic: "On jiachen day the emperor made a southern tour." },
  { zh: "三月，戊午朔，日有食之。", literal: "In the third month, on the new moon of the day wuwu, the sun was eclipsed.", idiomatic: "In the third month, on the new moon of wuwu day, there was a solar eclipse." },
  { zh: "庚申，帝至宛，不豫。", literal: "On the day gengshen, the emperor reached Wan and was unwell.", idiomatic: "On gengshen day the emperor reached Wan and fell ill." },
  { zh: "乙丑，帝發自宛；", literal: "On the day yichou, the emperor set out from Wan;", idiomatic: "On yichou day the emperor set out from Wan;" },
  { zh: "丁卯，至葉，崩於乘輿。", literal: "on the day dingmao, he reached Ye and died in the imperial carriage.", idiomatic: "on dingmao day he reached Ye and died in the imperial carriage." },
  { zh: "年三十二。", literal: "His age was thirty-two.", idiomatic: "He was thirty-two years old." },
  { zh: "皇后與閻顯兄弟、江京、樊豐等謀曰：「今晏駕道次，濟陰王在內，邂逅公卿立之，還為大害。", literal: "The empress, together with Yan Xian's brothers, Jiang Jing, Fan Feng, and the rest, plotted, saying, \"Now the carriage rests by the way; the Prince of Jibei is within the palace. Should the grand ministers by chance install him, on return it will become a great harm.\"", idiomatic: "The empress, together with Yan Xian's brothers, Jiang Jing, Fan Feng, and the rest, plotted, saying, \"The emperor has died on the road, and the Prince of Jibei is in the palace. If the grand ministers by chance install him, on our return it will be a great disaster.\"" },
  { zh: "」乃偽云「帝疾甚」，徙御臥車，所在上食、問起居如故。", literal: "\" They thereupon falsely announced \"the emperor's illness is severe,\" moved him to the imperial sleeping carriage, and at each place food was presented and inquiries after his health continued as before.", idiomatic: "\" They thereupon falsely announced that \"the emperor's illness is severe,\" moved him to the imperial sleeping carriage, and at each stop food was presented and inquiries after his health continued as before." },
  { zh: "驅馳行四日，庚午，還宮。", literal: "They drove in haste for four days; on the day gengwu they returned to the palace.", idiomatic: "They drove in haste for four days; on gengwu day they returned to the palace." },
  { zh: "辛未，遣司徒劉熹詣郊廟、社稷，告天請命；", literal: "On the day xinwei, Minister of Education Liu Xi was sent to the suburban altars, temples, and altars of soil and grain to announce to Heaven and request mandate;", idiomatic: "On xinwei day Minister of Education Liu Xi was sent to the suburban altars, temples, and the altars of soil and grain to announce to Heaven and request mandate;" },
  { zh: "其夕，發喪。", literal: "that evening the mourning was proclaimed.", idiomatic: "that evening mourning was proclaimed." },
  { zh: "尊皇后曰皇太后。", literal: "The empress was honored as empress dowager.", idiomatic: "The empress was honored as empress dowager." },
  { zh: "太后臨朝。", literal: "The empress dowager presided over court.", idiomatic: "The empress dowager presided over court." },
  { zh: "以顯為車騎將軍、儀同三司。", literal: "Xian was made General of Chariots and Cavalry with protocol equal to the Three Excellencies.", idiomatic: "Xian was made General of Chariots and Cavalry with protocol equal to the Three Excellencies." },
  { zh: "太后欲久專國政，貪立幼年，與顯等定策禁中，迎濟北惠王子北鄉侯懿為嗣。", literal: "The empress dowager wished to monopolize state affairs for long, was greedy to install a young child, and with Xian and the rest fixed the succession within the Forbidden Quarter, welcoming Prince Hui of Jibei's son, Marquis of North Village Yi, as heir.", idiomatic: "The empress dowager wished to monopolize state affairs for long and was eager to install a young child. With Xian and the rest she fixed the succession within the inner palace and welcomed Prince Hui of Jibei's son, Marquis of North Village Yi, as heir." },
  { zh: "濟陰王以廢黜，不得上殿親臨梓宮，悲號不食；", literal: "The Prince of Jibei, because he was deposed and dismissed, could not ascend the hall to attend the coffin in person, wailed in grief and would not eat;", idiomatic: "The Prince of Jibei, having been deposed, could not ascend the hall to attend the coffin in person. He wailed in grief and would not eat;" },
  { zh: "內外群僚莫不哀之。", literal: "within and without, the host of officials none failed to grieve for him.", idiomatic: "officials within and without all grieved for him." },
  { zh: "甲戌，濟南孝王香薨，無子，國絕。", literal: "On the day jiaxu, Prince Xiao of Jinan Xiang died without sons; the state was extinguished.", idiomatic: "On jiaxu day Prince Xiao of Jinan Xiang died without heirs and the state was extinguished." },
  { zh: "乙酉，北鄉侯即皇帝位。", literal: "On the day yiyou, the Marquis of North Village assumed the imperial throne.", idiomatic: "On yiyou day the Marquis of North Village assumed the imperial throne." },
  { zh: "夏，四月，丁酉，太尉馮石為太傅，司徒劉熹為太尉，參錄尚書事，前司空李郃為司徒。", literal: "In summer, the fourth month, on the day dingyou, Grand Commandant Feng Shi became Grand Tutor; Minister of Education Liu Xi became Grand Commandant and participated in recording Masters of Writing affairs; former Minister of Works Li He became Minister of Education.", idiomatic: "In summer, in the fourth month, on dingyou day Grand Commandant Feng Shi became Grand Tutor; Minister of Education Liu Xi became Grand Commandant and participated in recording Masters of Writing affairs; former Minister of Works Li He became Minister of Education." },
  { zh: "閻顯忌大將軍耿寶位尊權重，威行前朝，乃風有司奏「寶及其黨與中常侍樊豐、虎賁中郎將謝惲、侍中周廣、野王君王聖、聖女永等更相阿黨，互作威福，皆大不道。", literal: "Yan Xian resented that Grand General Geng Bao's position was honored and his power heavy, his authority moving through the former court. He therefore prompted the responsible offices to memorialize that \"Bao and his faction, together with Palace Attendant Fan Feng, Colonel of the Rapid Tigers Xie Yun, Palace Attendant Zhou Guang, Prince of Yewang Wang Sheng, and Sheng's daughter Yong and the rest, repeatedly fawned on one another as a clique, each making authority and blessing for himself—all were greatly unfilial.\"", idiomatic: "Yan Xian resented Grand General Geng Bao's honored position and heavy power, his authority still felt from the former court. He therefore prompted the responsible offices to memorialize that \"Bao and his faction, together with Palace Attendant Fan Feng, Colonel of the Rapid Tigers Xie Yun, Palace Attendant Zhou Guang, Prince of Yewang Wang Sheng, and Sheng's daughter Yong and the rest, repeatedly formed a clique, each making authority and blessing for himself—all were greatly unfilial.\"" },
  { zh: "」辛卯，豐、惲、廣皆下獄，死；", literal: "\" On the day xinmao, Feng, Yun, and Guang were all imprisoned and died;", idiomatic: "\" On xinmao day Feng, Yun, and Guang were all imprisoned and executed;" },
  { zh: "家屬徙比景。", literal: "their families were relocated to Bijing.", idiomatic: "their families were relocated to Bijing." },
  { zh: "貶寶及弟子林慮侯承皆為亭侯，遣就國；", literal: "Bao and his nephew Marquis of Linlu Cheng were both demoted to marquises of ting and sent to their states;", idiomatic: "Bao and his nephew Marquis of Linlu Cheng were both demoted to ting marquises and sent to their states;" },
  { zh: "寶於道自殺。", literal: "Bao killed himself on the road.", idiomatic: "Bao killed himself on the road." },
  { zh: "王聖母子徙雁門。", literal: "Wang Sheng and his mother were relocated to Yanmen.", idiomatic: "Wang Sheng and his mother were relocated to Yanmen." },
  { zh: "於是以閻景為衛尉，耀為城門校尉，晏為執金吾，兄弟並處權要，威福自由。", literal: "Thereupon Yan Jing was made Commandant of the Guards, Yao made Colonel of the City Gates, and Yan made Bearer of the Gilded Mace; the brothers all held power posts, authority and blessing at their own disposal.", idiomatic: "Thereupon Yan Jing was made Commandant of the Guards, Yao Colonel of the City Gates, and Yan Bearer of the Gilded Mace; the brothers all held power posts, authority and blessing at their own disposal." },
  { zh: "己酉，葬孝安皇帝於恭陵，廟曰恭宗。", literal: "On the day jiyou, Emperor Xiaoan was buried at Gong tomb; his temple name was Gongzong.", idiomatic: "On jiyou day Emperor An was buried at Gong tomb; his temple name was Gongzong." },
  { zh: "六月，乙巳，赦天下。", literal: "In the sixth month, on the day yisi, the realm was pardoned.", idiomatic: "In the sixth month, on yisi day, the realm was pardoned." },
  { zh: "秋，七月，西域長史班勇發敦煌、張掖、酒泉六千騎及鄯善、疏勒、車師前部兵擊後部王軍就，大破之，獲首虜八千餘人，生得軍就及匈奴持節使者，將至索班沒處斬之，傳首京師。", literal: "In autumn, the seventh month, Chief Clerk of the Western Regions Ban Yong dispatched six thousand cavalry from Dunhuang, Zhangye, and Jiuquan, together with troops of Shanshan, Shule, and the Former Department of Cheshi, to strike the Later King Junjiu and greatly defeated him, capturing more than eight thousand heads and prisoners alive. Junjiu and the Xiongnu envoy bearing credentials were taken alive, brought to the place where Suo Ban perished and beheaded, and the head was sent to the capital.", idiomatic: "In autumn, in the seventh month, Western Regions Chief Clerk Ban Yong dispatched six thousand cavalry from Dunhuang, Zhangye, and Jiuquan, together with troops of Shanshan, Shule, and the Former Department of Cheshi, to strike the Later King Junjiu and routed him, taking more than eight thousand heads and captives. Junjiu and the Xiongnu envoy bearing credentials were captured alive, brought to the place where Suo Ban had died and beheaded, and the head was sent to the capital." },
  { zh: "冬，十月，丙午，越巂山崩。", literal: "In winter, the tenth month, on the day bingwu, a mountain in Yuexi collapsed.", idiomatic: "In winter, in the tenth month, on bingwu day, a mountain in Yuexi collapsed." },
  { zh: "北鄉侯病篤，中常侍孫程謂濟陰王謁者長興渠曰：「王以嫡統，本無失德。", literal: "The Marquis of North Village's illness was grave. Palace Attendant Sun Cheng said to the Prince of Jibei's Chief of Ushers Xing Qu, \"The prince, by legitimate succession, originally had no lost virtue.\"", idiomatic: "The Marquis of North Village's illness was grave. Palace Attendant Sun Cheng said to the Prince of Jibei's Chief of Ushers Xing Qu, \"The prince, as legitimate heir, originally had no lost virtue.\"" },
  { zh: "先帝用讒，遂至廢黜。", literal: "\"The former emperor used slander, and it reached deposal and dismissal.\"", idiomatic: "\"The former emperor listened to slander and deposed him.\"" },
  { zh: "若北鄉侯不起，相與共斷江京、閻顯，事無不成者。", literal: "\"If the Marquis of North Village does not recover, let us together cut down Jiang Jing and Yan Xian—nothing will fail to succeed.\"", idiomatic: "\"If the Marquis of North Village does not recover, let us together cut down Jiang Jing and Yan Xian—nothing will fail.\"" },
  { zh: "」渠然之。", literal: "\" Qu assented.", idiomatic: "\" Qu agreed." },
  { zh: "又中黃門南陽王康，先為太子府史，及長樂太官丞京兆王國等並附同於程。", literal: "Also Central Yellow Gate Wang Kang of Nanyang, who had earlier been a clerk in the crown prince's household, and Chief Steward of Everlasting Joy Wang Guo of Jingzhao and the rest all attached themselves to Cheng in agreement.", idiomatic: "Also Central Yellow Gate Wang Kang of Nanyang, who had earlier been a clerk in the crown prince's household, and Chief Steward of Everlasting Joy Wang Guo of Jingzhao and the rest all joined Cheng's cause." },
  { zh: "江京謂閻顯曰：「北鄉侯病不解，國嗣宜以時定，何不早徵諸王子，簡所置乎！", literal: "Jiang Jing said to Yan Xian, \"The Marquis of North Village's illness does not ease; the state heir ought to be fixed in season—why not early summon the various princes and select whom to install!\"", idiomatic: "Jiang Jing said to Yan Xian, \"The Marquis of North Village's illness does not ease; the succession ought to be settled in time—why not early summon the various princes and choose whom to install!\"" },
  { zh: "」顯以為然。", literal: "\" Xian thought it so.", idiomatic: "\" Xian agreed." },
  { zh: "辛亥，北鄉侯薨。", literal: "On the day xinhai, the Marquis of North Village died.", idiomatic: "On xinhai day the Marquis of North Village died." },
  { zh: "顯白太后，秘不發喪，而更徵諸王子，閉宮門，屯兵自守。", literal: "Xian reported to the empress dowager, kept the death secret and did not proclaim mourning, and instead again summoned the various princes, closed the palace gates, and garrisoned troops to guard himself.", idiomatic: "Xian reported to the empress dowager, kept the death secret and did not proclaim mourning, and instead again summoned the various princes, closed the palace gates, and garrisoned troops to guard himself." },
  { zh: "十一月，乙卯，孫程、王康、王國與中黃門黃龍、彭愷、孟叔、李建、王成、張賢、史泛、馬國、王道、李元、楊佗、陳予、趙封、李剛、魏猛、苗光等聚謀於西鐘下，皆截單衣為誓。", literal: "In the eleventh month, on the day yimao, Sun Cheng, Wang Kang, Wang Guo, together with Central Yellow Gates Huang Long, Peng Kai, Meng Shu, Li Jian, Wang Cheng, Zhang Xian, Shi Fan, Ma Guo, Wang Dao, Li Yuan, Yang Tuo, Chen Yu, Zhao Feng, Li Gang, Wei Meng, Miao Guang, and the rest gathered to plot beneath the Western Bell. All cut their unlined garments as oath.", idiomatic: "In the eleventh month, on yimao day, Sun Cheng, Wang Kang, Wang Guo, together with Central Yellow Gates Huang Long, Peng Kai, Meng Shu, Li Jian, Wang Cheng, Zhang Xian, Shi Fan, Ma Guo, Wang Dao, Li Yuan, Yang Tuo, Chen Yu, Zhao Feng, Li Gang, Wei Meng, Miao Guang, and the rest gathered to plot beneath the Western Bell. All cut their unlined garments as oath." },
  { zh: "丁巳，京師及郡國十六地震。", literal: "On the day dingsi, the capital and sixteen commanderies and kingdoms had earthquakes.", idiomatic: "On dingsi day the capital and sixteen commanderies and kingdoms suffered earthquakes." },
  { zh: "是夜，程等共會崇德殿上，因入章臺門。", literal: "That night Cheng and the rest jointly met atop Chongde Hall and thereupon entered Zhangtai Gate.", idiomatic: "That night Cheng and the rest met atop Chongde Hall and entered Zhangtai Gate." },
  { zh: "時江京、劉發及李閏、陳達等俱坐省門下，程與王康共就斬京、安、達。", literal: "At the time Jiang Jing, Liu Fa, and Li Run and Chen Da and the rest were all seated beneath the Secretariat gate. Cheng and Wang Kang together went and beheaded Jing, An, and Da.", idiomatic: "At the time Jiang Jing, Liu Fa, and Li Run and Chen Da and the rest were all seated beneath the Secretariat gate. Cheng and Wang Kang went together and beheaded Jing, An, and Da." },
  { zh: "以李閏權勢積為省內所服，欲引為主，因舉刃脅閏曰：「今當立濟陰王，無得搖動！", literal: "Because Li Run's accumulated authority and power made him one whom those within the Secretariat submitted to, they wished to draw him as leader and thereupon raised blades to coerce Run, saying, \"Now we must install the Prince of Jibei—none may stir!\"", idiomatic: "Because Li Run's accumulated authority made him one whom those within the Secretariat obeyed, they wished to make him their leader and raised blades to coerce him, saying, \"Now we must install the Prince of Jibei—none may stir!\"" },
  { zh: "」閏曰：「諾。", literal: "\" Run said, \"Yes.\"", idiomatic: "\" Run said, \"Yes.\"" },
  { zh: "」於是扶閏起，俱於西鐘下迎濟陰王即皇帝位，時年十一。", literal: "\" Thereupon they helped Run rise, and all together beneath the Western Bell welcomed the Prince of Jibei to assume the imperial throne. His age was then eleven.", idiomatic: "\" Thereupon they helped Run rise, and all together beneath the Western Bell welcomed the Prince of Jibei to the throne. He was then eleven years old." },
  { zh: "召尚書令、僕射以下從輦幸南宮，程等留守省門，遮扞內外。", literal: "The Masters of Writing Director, Vice Director, and those below were summoned to follow the carriage in visiting the Southern Palace. Cheng and the rest remained to guard the Secretariat gate, blocking and defending within and without.", idiomatic: "The Director of the Masters of Writing, Vice Director, and those below were summoned to follow the carriage to the Southern Palace. Cheng and the rest remained to guard the Secretariat gate, blocking access within and without." },
  { zh: "帝登雲台，召公卿、百僚，使虎賁、羽林士屯南、北宮諸門。", literal: "The emperor ascended Cloud Terrace, summoned the ducal ministers and the hundred officials, and ordered Rapid Tiger and Forest guards to garrison the various gates of the Southern and Northern Palaces.", idiomatic: "The emperor ascended Cloud Terrace, summoned the ducal ministers and the hundred officials, and ordered Rapid Tiger and Forest guards to garrison the gates of the Southern and Northern Palaces." },
  { zh: "閻顯時在禁中，憂迫不知所為，小黃門樊登勸顯以太后詔召越騎校尉馮詩、虎賁中郎將閻崇將兵屯平朔門以御程等。", literal: "Yan Xian was then within the Forbidden Quarter, distressed and pressed, not knowing what to do. Junior Yellow Gate Fan Deng urged Xian, by the empress dowager's edict, to summon Colonel of the Rapid Cavalry Feng Shi and Colonel of the Rapid Tigers Yan Chong to lead troops and garrison Ping Gate to resist Cheng and the rest.", idiomatic: "Yan Xian was then within the inner palace, distressed and at a loss. Junior Yellow Gate Fan Deng urged him, by the empress dowager's edict, to summon Colonel of the Rapid Cavalry Feng Shi and Colonel of the Rapid Tigers Yan Chong to lead troops and garrison Ping Gate to resist Cheng and the rest." },
  { zh: "顯誘詩入省，謂曰：「濟陰王立，非皇太后意，璽綬在此。", literal: "Xian enticed Shi to enter the Secretariat and said to him, \"The Prince of Jibei's installation is not the empress dowager's intent. The seal and cord are here.\"", idiomatic: "Xian lured Shi into the Secretariat and said to him, \"The Prince of Jibei's installation is not the empress dowager's intent. The seal and cord are here.\"" },
  { zh: "苟盡力效功，封侯可得。", literal: "\"If you exhaust your strength in rendering achievement, enfeoffment as marquis can be obtained.\"", idiomatic: "\"If you exhaust your strength in service, you can be enfeoffed as marquis.\"" },
  { zh: "」太后使授之印曰：「能得濟陰王者，封萬戶侯；", literal: "\" The empress dowager sent someone to grant him a seal, saying, \"Whoever can obtain the Prince of Jibei shall be enfeoffed as marquis of ten thousand households;\"", idiomatic: "\" The empress dowager sent someone to grant him a seal, saying, \"Whoever can obtain the Prince of Jibei shall be enfeoffed as marquis of ten thousand households;\"" },
  { zh: "得李閏者，五千戶侯。", literal: "\"whoever can obtain Li Run shall be enfeoffed as marquis of five thousand households.\"", idiomatic: "\"whoever can obtain Li Run shall be enfeoffed as marquis of five thousand households.\"" },
  { zh: "」詩等皆許諾，辭以「卒被召，所將眾少。", literal: "\" Shi and the rest all promised, excusing themselves that \"the soldiers were suddenly summoned; the masses I lead are few.\"", idiomatic: "\" Shi and the rest all promised, excusing themselves that \"the soldiers were suddenly summoned; the men I lead are few.\"" },
  { zh: "」顯使與登迎吏士於左掖門外，詩因格殺登，歸營屯守。", literal: "\" Xian sent him together with Deng to welcome officials and soldiers outside the Left Flank Gate. Shi thereupon struck and killed Deng, returned to camp, and garrisoned in defense.", idiomatic: "\" Xian sent him with Deng to welcome officials and soldiers outside the Left Flank Gate. Shi thereupon struck and killed Deng, returned to camp, and garrisoned in defense." },
  { zh: "顯弟衛尉景遽從省中還外府，收兵至盛德門。", literal: "Xian's younger brother Commandant of the Guards Jing hastily returned from the Secretariat to the outer offices, gathered troops, and reached Shengde Gate.", idiomatic: "Xian's younger brother Commandant of the Guards Jing hastily returned from the Secretariat to the outer offices, gathered troops, and reached Shengde Gate." },
  { zh: "孫程傳召諸尚書使收景。", literal: "Sun Cheng transmitted summons to the various Masters of Writing to have Jing arrested.", idiomatic: "Sun Cheng transmitted summons to the various Masters of Writing to have Jing arrested." },
  { zh: "尚書郭鎮時臥病，聞之，即率直宿羽林出南止車門，逢景從吏士拔白刃呼曰：「無干兵！", literal: "Master of Writing Guo Zhen was then ill abed. Hearing of it, he immediately led the on-duty Forest guards out through the Southern Gate Where Chariots Stop, met Jing's following officials and soldiers drawing bright blades, and shouted, \"None interfere with the troops!\"", idiomatic: "Master of Writing Guo Zhen was then ill in bed. Hearing of it, he immediately led the on-duty Forest guards out through the Southern Gate Where Chariots Stop, met Jing's following officials and soldiers drawing bright blades, and shouted, \"None interfere with the troops!\"" },
  { zh: "」鎮即下車持節詔之，景曰：「何等詔！", literal: "\" Zhen immediately descended the carriage, held credentials, and proclaimed to him. Jing said, \"What sort of proclamation!\"", idiomatic: "\" Zhen immediately descended the carriage, held credentials, and proclaimed to him. Jing said, \"What sort of proclamation!\"" },
  { zh: "」因斫鎮，不中。", literal: "\" He thereupon hacked at Zhen and missed.", idiomatic: "\" He hacked at Zhen and missed." },
  { zh: "鎮引劍擊景墮車，左右以戟叉其胸，遂禽之，送廷尉獄，即夜死。", literal: "Zhen drew his sword, struck Jing, and knocked him from the carriage. Those at left and right used halberds to pin his chest, then captured him and sent him to the Minister of Justice's prison. That very night he died.", idiomatic: "Zhen drew his sword, struck Jing, and knocked him from the carriage. His attendants pinned his chest with halberds, captured him, and sent him to the Minister of Justice's prison. That very night he died." },
  { zh: "戊午，遣使者入省，奪得璽綬，帝乃幸嘉德殿，遣侍御史持節收閻顯及其弟城門校尉耀、執金吾晏，並下獄，誅；", literal: "On the day wuwu, envoys were sent into the Secretariat; the seal and cord were seized. The emperor thereupon visited Jiade Hall, sent Palace Attendants bearing credentials to arrest Yan Xian and his younger brothers Colonel of the City Gates Yao and Bearer of the Gilded Mace Yan, and all were imprisoned and executed;", idiomatic: "On wuwu day envoys were sent into the Secretariat and the seal and cord were seized. The emperor thereupon visited Jiade Hall, sent Attending Censors bearing credentials to arrest Yan Xian and his younger brothers Colonel of the City Gates Yao and Bearer of the Gilded Mace Yan, and all were imprisoned and executed;" },
  { zh: "家屬皆徙比景。", literal: "their families were all relocated to Bijing.", idiomatic: "their families were all relocated to Bijing." },
  { zh: "遷太后於離宮。", literal: "The empress dowager was moved to a detached palace.", idiomatic: "The empress dowager was moved to a detached palace." },
  { zh: "己未，開門，罷屯兵。", literal: "On the day jiwei, the gates were opened and garrison troops were dismissed.", idiomatic: "On jiwei day the gates were opened and garrison troops were dismissed." },
  { zh: "壬戌，詔司隸校尉：「惟閻顯、江京近親，當伏辜誅，其餘務崇寬貸。", literal: "On the day renxu, an edict to the Colonel of the Metropolitan Area said, \"Only Yan Xian and Jiang Jing's close kin ought to bear guilt and suffer execution; the rest should be treated with generous leniency.\"", idiomatic: "On renxu day an edict to the Colonel of the Metropolitan Area said, \"Only Yan Xian and Jiang Jing's close kin ought to bear guilt and suffer execution; the rest should be treated with generous leniency.\"" },
  { zh: "封孫程等皆為列侯：程食邑萬戶，王康、王國食九千戶，黃龍食五千戶，彭愷、孟叔、李建食四千二百戶，王成、張賢、史泛、馬國、王道、李元、楊佗、陳予、趙封、李剛食四千戶，魏猛食二千戶，苗光食千戶：是為十九侯，加賜車馬、金銀、錢帛各有差；", literal: "Sun Cheng and the rest were all enfeoffed as ranked marquises: Cheng's fief was ten thousand households; Wang Kang and Wang Guo nine thousand households; Huang Long five thousand households; Peng Kai, Meng Shu, and Li Jian four thousand two hundred households; Wang Cheng, Zhang Xian, Shi Fan, Ma Guo, Wang Dao, Li Yuan, Yang Tuo, Chen Yu, Zhao Feng, and Li Gang four thousand households; Wei Meng two thousand households; Miao Guang one thousand households—these were the nineteen marquises. Carriages, horses, gold, silver, cash, and silks were added in gifts, each according to rank;", idiomatic: "Sun Cheng and the rest were all enfeoffed as ranked marquises: Cheng's fief was ten thousand households; Wang Kang and Wang Guo nine thousand; Huang Long five thousand; Peng Kai, Meng Shu, and Li Jian four thousand two hundred; Wang Cheng, Zhang Xian, Shi Fan, Ma Guo, Wang Dao, Li Yuan, Yang Tuo, Chen Yu, Zhao Feng, and Li Gang four thousand; Wei Meng two thousand; Miao Guang one thousand—these were the nineteen marquises. Carriages, horses, gold, silver, cash, and silks were added as gifts, each according to rank;" },
  { zh: "李閏以先不豫謀，故不封。", literal: "Li Run, because he had earlier not been in the plot, was therefore not enfeoffed.", idiomatic: "Li Run, because he had not been in on the plot from the start, was not enfeoffed." },
  { zh: "擢孫程為騎都尉。", literal: "Sun Cheng was promoted to Colonel of Cavalry.", idiomatic: "Sun Cheng was promoted to Colonel of Cavalry." },
  { zh: "初，程等入章台門，苗光獨不入。", literal: "Earlier, when Cheng and the rest entered Zhangtai Gate, Miao Guang alone did not enter.", idiomatic: "Earlier, when Cheng and the rest entered Zhangtai Gate, Miao Guang alone did not enter." },
  { zh: "詔書錄功臣，令王康疏名，康詐疏光入章台門。", literal: "An edict ordered the recording of meritorious subjects and commanded Wang Kang to list names. Kang falsely listed Guang as having entered Zhangtai Gate.", idiomatic: "An edict ordered the recording of meritorious subjects and commanded Wang Kang to list names. Kang falsely listed Guang as having entered Zhangtai Gate." },
  { zh: "光未受符策，心不自安，詣黃門令自告。", literal: "Guang had not received credentials and edicts; his heart was not at ease, and he went to the Yellow Gate Director to confess himself.", idiomatic: "Guang had not received credentials and edicts; uneasy in heart, he went to the Yellow Gate Director to confess." },
  { zh: "有司奏康、光欺詐主上；", literal: "The responsible offices memorialized that Kang and Guang had deceived and cheated the sovereign;", idiomatic: "The responsible offices memorialized that Kang and Guang had deceived the sovereign;" },
  { zh: "詔書勿問。", literal: "an edict ordered that they not be questioned.", idiomatic: "an edict ordered that they not be questioned." },
  { zh: "以將作大匠來歷為衛尉。", literal: "Chief Artisan for Palace Construction Lai Li was made Commandant of the Guards.", idiomatic: "Chief Artisan for Palace Construction Lai Li was made Commandant of the Guards." },
  { zh: "祋諷、劉瑋、閭丘弘等先卒，皆拜其子為郎。", literal: "Di Feng, Liu Wei, Luqiu Hong, and the rest had died earlier; all their sons were appointed gentlemen.", idiomatic: "Di Feng, Liu Wei, Luqiu Hong, and the rest had died earlier; all their sons were appointed gentlemen." },
  { zh: "朱倀、施延、陳光、趙代皆見拔用，後至公卿。", literal: "Zhu Chang, Shi Yan, Chen Guang, and Zhao Dai were all seen and promoted to employment; later they reached ducal ministers.", idiomatic: "Zhu Chang, Shi Yan, Chen Guang, and Zhao Dai were all promoted; later they reached ducal rank." },
  { zh: "徵王男、邴吉家屬還京師，厚加賞賜。", literal: "The families of Wang Nan and Bing Ji were summoned back to the capital and generously rewarded.", idiomatic: "The families of Wang Nan and Bing Ji were summoned back to the capital and generously rewarded." },
  { zh: "帝之見廢也，監太子家小黃門籍建、傅高梵、長秋長趙熹、丞良賀、藥長夏珍皆坐徙朔方；", literal: "When the emperor had been deposed, the junior yellow gates supervising the crown prince's household Ji Jian and Fu Gaofan, Chief of Everlasting Autumn Zhao Xi, Assistant Liang He, and Chief of Medicines Xia Zhen were all charged and relocated to Shuofang;", idiomatic: "When the emperor had been deposed, the junior yellow gates supervising the crown prince's household Ji Jian and Fu Gaofan, Chief of Everlasting Autumn Zhao Xi, Assistant Liang He, and Chief of Medicines Xia Zhen had all been charged and relocated to Shuofang;" },
  { zh: "帝即位，並擢為中常侍。", literal: "when the emperor assumed the throne, all were promoted to palace attendants.", idiomatic: "when the emperor took the throne, all were promoted to palace attendants." },
  { zh: "初，閻顯辟崔□因之子瑗為吏，瑗以北鄉侯立不以正，知顯將敗，欲說令廢立，而顯日沉醉，不能得見，乃謂長史陳禪曰：「中常侍江京等惑蠱先帝，廢黜正統，扶立疏孽。", literal: "Earlier, Yan Xian recruited Cui □'s son Yuan as a clerk. Yuan, because the Marquis of North Village's installation was not by the proper way, knew Xian would fail and wished to persuade him to depose and install, but Xian daily was deep in drink and could not be seen. He thereupon said to Chief Clerk Chen Chan, \"Palace Attendants Jiang Jing and the rest deluded and bewitched the former emperor, deposed and dismissed the legitimate succession, and propped up a distant offshoot.\"", idiomatic: "Earlier Yan Xian recruited Cui □'s son Yuan as a clerk. Yuan, seeing the Marquis of North Village installed improperly, knew Xian would fail and wished to persuade him to depose and install, but Xian was daily deep in drink and could not be seen. He thereupon said to Chief Clerk Chen Chan, \"Palace Attendants Jiang Jing and the rest deluded the former emperor, deposed the legitimate heir, and propped up a distant offshoot.\"" },
  { zh: "少帝即位，發病廟中，周勃之徵，於斯復見。", literal: "\"The young emperor assumed the throne and fell ill in the ancestral temple—the sign of Zhou Bo appears again at this moment.\"", idiomatic: "\"The young emperor took the throne and fell ill in the ancestral temple—the sign of Zhou Bo appears again at this moment.\"" },
  { zh: "今欲與君共求見說將軍，白太后，收京等，廢少帝，引立濟陰王，必上當天心，下合人望，伊、霍之功不下席而立，則將軍兄弟傳祚於無窮；", literal: "\"Now I wish together with you to seek an audience and persuade the general, report to the empress dowager, arrest Jing and the rest, depose the young emperor, and draw forth the installation of the Prince of Jibei. Above it will surely match Heaven's heart; below it will join human expectation. The achievements of Yi Yin and Huo Guang—without leaving one's seat one may stand—then the general's brothers will transmit the throne without end;\"", idiomatic: "\"Now I wish together with you to seek an audience and persuade the general, report to the empress dowager, arrest Jing and the rest, depose the young emperor, and install the Prince of Jibei. Above it will match Heaven's heart; below it will join human expectation. The achievements of Yi Yin and Huo Guang—won without leaving one's seat—then the general's brothers will transmit favor without end;\"" },
  { zh: "若拒違天意，久曠神器，則將以無罪並辜元惡。", literal: "\"if you reject and defy Heaven's intent and long leave the sacred vessel vacant, then you will be punished without guilt together with the chief villain.\"", idiomatic: "\"if you reject Heaven's intent and long leave the throne vacant, you will be punished without guilt together with the chief villain.\"" },
  { zh: "此所謂禍福之會，分功之時也。", literal: "\"This is what is called the meeting of fortune and calamity, the time to divide achievement.\"", idiomatic: "\"This is the meeting of fortune and calamity, the time to divide achievement.\"" },
  { zh: "」禪猶豫未敢從。", literal: "\" Chan hesitated and did not dare follow.", idiomatic: "\" Chan hesitated and did not dare agree." },
  { zh: "會顯敗，瑗坐被斥；", literal: "It happened that Xian failed; Yuan was charged and dismissed;", idiomatic: "It happened that Xian failed; Yuan was charged and dismissed;" },
  { zh: "門生蘇祗欲上書言狀，瑗遽止之。", literal: "his student Su Zhi wished to submit a memorial stating the facts, but Yuan hastily stopped him.", idiomatic: "his student Su Zhi wished to submit a memorial stating the facts, but Yuan hastily stopped him." },
  { zh: "時陳禪為司隸校尉，召瑗謂曰：「弟聽祗上書，禪請為之證。", literal: "At the time Chen Chan was Colonel of the Metropolitan Area. He summoned Yuan and said, \"Younger brother, let Zhi submit the memorial—I, Chan, ask to testify for it.\"", idiomatic: "At the time Chen Chan was Colonel of the Metropolitan Area. He summoned Yuan and said, \"Younger brother, let Zhi submit the memorial—I, Chan, ask to testify for it.\"" },
  { zh: "」瑗曰：「此譬猶兒妾屏語耳，願使君勿復出口。", literal: "\" Yuan said, \"This is like the whispered words of a child concubine behind a screen—I wish the lord would never speak of it again.\"", idiomatic: "\" Yuan said, \"This is like a child concubine's whisper behind a screen—I beg you never speak of it again.\"" },
  { zh: "」遂辭歸，不復應州郡命。", literal: "\" He thereupon took leave and returned, and no longer responded to commandery and provincial orders.", idiomatic: "\" He thereupon took leave and returned, and no longer responded to commandery and provincial orders." },
  { zh: "己卯，以諸王禮葬北鄉侯。", literal: "On the day jimao, the Marquis of North Village was buried with the rites of the various princes.", idiomatic: "On jimao day the Marquis of North Village was buried with the rites due a prince." },
  { zh: "司空劉授以阿附惡逆，辟召非其人，策免。", literal: "Minister of Works Liu Shou, for fawning on the wicked and rebellious and recruiting not the proper men, was dismissed by written impeachment.", idiomatic: "Minister of Works Liu Shou, for fawning on the wicked and rebellious and recruiting improper men, was impeached and dismissed." },
  { zh: "十二月，甲申，以少府河南陶敦為司空。", literal: "In the twelfth month, on the day jiashen, Intendant of the Palace Treasury Tao Dun of Henan was made Minister of Works.", idiomatic: "In the twelfth month, on jiashen day, Intendant of the Palace Treasury Tao Dun of Henan was made Minister of Works." },
  { zh: "楊震門生虞放、陳翼詣闕追訟震事；", literal: "Yang Zhen's students Yu Fang and Chen Yi came to the gate to pursue and plead Zhen's case;", idiomatic: "Yang Zhen's students Yu Fang and Chen Yi came to court to pursue and plead Zhen's case;" },
  { zh: "詔除震二子為郎，贈錢百萬，以禮改葬於華陰潼亭，遠近畢至。", literal: "an edict appointed Zhen's two sons as gentlemen, bestowed a gift of a million cash, and by rite reburied him at Tong Pavilion in Huayin. From far and near all came.", idiomatic: "an edict appointed Zhen's two sons as gentlemen, bestowed a gift of a million cash, and by rite reburied him at Tong Pavilion in Huayin. From far and near all came." },
  { zh: "有大鳥高丈餘集震喪前，郡以狀上。", literal: "A large bird over a zhang tall gathered before Zhen's funeral; the commandery reported the matter upward.", idiomatic: "A large bird over a zhang tall gathered before Zhen's funeral; the commandery reported it to the throne." },
  { zh: "帝感震忠直，詔復以中牢具祠之。", literal: "The emperor was moved by Zhen's loyalty and uprightness and ordered that middle-grade sacrificial offerings again be used to worship him.", idiomatic: "Moved by Zhen's loyalty and uprightness, the emperor ordered middle-grade sacrificial offerings restored for his worship." },
  { zh: "議郎陳禪以為：「閻太后與帝無母子恩，宜徙別館，絕朝見，」群臣議者咸以為宜。", literal: "Consultation Gentleman Chen Chan held: \"Empress Dowager Yan and the emperor have no mother-son affection; she ought to be moved to a separate residence and court audiences cut off,\" and the ministers who discussed it all thought it fitting.", idiomatic: "Consultation Gentleman Chen Chan argued: \"Empress Dowager Yan and the emperor have no mother-son bond; she ought to be moved to a separate residence and court audiences ended.\" The ministers who discussed it all agreed." },
  { zh: "司徒掾汝南周舉謂李郃曰：「昔瞽瞍常欲殺舜，舜事之逾謹；", literal: "A clerk of the Minister over the Masses, Zhou Ju of Runan, said to Li He: \"In the past Gusou often wished to kill Shun, yet Shun served him all the more carefully;", idiomatic: "A clerk of the Minister over the Masses, Zhou Ju of Runan, said to Li He: \"In the past Gusou often wished to kill Shun, yet Shun served him all the more carefully;\"" },
  { zh: "鄭武姜謀殺莊公，莊公誓之黃泉，秦始皇怨母失行，久而隔絕，後感穎考叔、茅焦之言，復修子道；", literal: "Lady Wu of Zheng plotted to kill Duke Zhuang, and Duke Zhuang swore with her only in the Yellow Springs; Qin Shihuang resented his mother's misconduct, long kept apart, then was moved by the words of Ying Kaoshu and Mao Jiao and again practiced the son's way;", idiomatic: "Lady Wu of Zheng plotted to kill Duke Zhuang, and Duke Zhuang swore reunion only in the Yellow Springs; Qin Shihuang resented his mother's misconduct and long kept apart, then was moved by Ying Kaoshu and Mao Jiao and again practiced filial duty;\"" },
  { zh: "書傳美之。", literal: "the histories praise this.", idiomatic: "the histories praise this.\"" },
  { zh: "今諸閻新誅，太后幽在離宮，若悲愁生疾，一旦不虞，主上將何以令於天下！", literal: "Now the various Yans have just been executed and the empress dowager is secluded in a detached palace; if grief and sorrow bring illness and she meets sudden misfortune, how will our lord command all under Heaven!", idiomatic: "Now the Yan clan has just been executed and the empress dowager is secluded in a detached palace. If grief brings illness and she meets sudden misfortune, how will our lord command all under Heaven!\"" },
  { zh: "如從禪議，後世歸咎明公。", literal: "If we follow Chan's proposal, later ages will lay blame on Your Excellency.", idiomatic: "If we follow Chan's proposal, later ages will blame Your Excellency.\"" },
  { zh: "宜密表朝廷，令奉太后，率群臣朝覲如舊，以厭天心，以答人望！", literal: "You ought secretly to memorialize the court, have the empress dowager honored, and lead the ministers in audience as before, to satisfy Heaven's heart and answer men's hopes!\"", idiomatic: "You ought secretly to memorialize the court, have the empress dowager honored, and lead the ministers in audience as before, to satisfy Heaven and answer public expectation!\"" },
  { zh: "」郃即上疏陳之。", literal: "\" He at once submitted a memorial setting this forth.", idiomatic: "\" He at once submitted a memorial setting this forth." },
  { zh: "孝和皇帝上", literal: "Emperor He, Part One.", idiomatic: "Emperor He, Part One." },
  { zh: "春，正月，帝朝太后於東宮，太后意乃安。", literal: "In spring, the first month, the emperor attended the empress dowager at the Eastern Palace, and her mind was then at ease.", idiomatic: "In spring, in the first month, the emperor attended the empress dowager at the Eastern Palace, and her mind was eased." },
  { zh: "甲寅，赦天下。", literal: "On jiayin day, all under Heaven was amnestied.", idiomatic: "On jiayin day all under Heaven was amnestied." },
  { zh: "辛未，皇太后閻氏崩。", literal: "On xinwei day, the empress dowager of the Yan clan died.", idiomatic: "On xinwei day Empress Dowager Yan died." },
  { zh: "辛巳，太傅馮石、太尉劉熹以阿黨權貴免。", literal: "On xinsi day, Grand Tutor Feng Shi and Grand Commandant Liu Xi were dismissed for fawning on the powerful.", idiomatic: "On xinsi day Grand Tutor Feng Shi and Grand Commandant Liu Xi were dismissed for fawning on the powerful." },
  { zh: "司徒李郃罷。", literal: "Minister over the Masses Li He was removed.", idiomatic: "Minister over the Masses Li He was dismissed." },
  { zh: "二月，甲申，葬安思皇后。", literal: "In the second month, on jiashen day, Empress Ansi was buried.", idiomatic: "In the second month, on jiashen day, Empress Ansi was buried." },
  { zh: "丙戌，以太常桓焉為太傅；", literal: "On bingxu day, Grand Master of Ceremonies Huan Yan was made Grand Tutor;", idiomatic: "On bingxu day Grand Master of Ceremonies Huan Yan was made Grand Tutor;" },
  { zh: "大鴻臚京兆朱寵為太尉，參錄尚書事；", literal: "Grand Herald Zhu Chong of Jingzhao was made Grand Commandant and participated in recording Masters of Writing affairs;", idiomatic: "Grand Herald Zhu Chong of Jingzhao was made Grand Commandant and joined in recording Masters of Writing affairs;" },
  { zh: "長樂少府朱倀為司徒。", literal: "Changle Chamberlain Zhu Yi was made Minister over the Masses.", idiomatic: "Changle Chamberlain Zhu Yi was made Minister over the Masses." },
  { zh: "封尚書郭鎮為定穎侯。", literal: "Master of Writing Guo Zhen was enfeoffed as Marquis of Dingying.", idiomatic: "Master of Writing Guo Zhen was enfeoffed as Marquis of Dingying." },
  { zh: "隴西鐘羌反，校尉馬賢擊之，戰於臨洮，斬首千餘級，羌眾皆降；", literal: "The Zhong Qiang of Longxi rebelled; Colonel Ma Xian attacked them, fought at Lintao, beheaded more than a thousand, and the Qiang masses all submitted;", idiomatic: "The Zhong Qiang of Longxi rebelled. Colonel Ma Xian attacked them at Lintao, took more than a thousand heads, and the Qiang all submitted;" },
  { zh: "由是涼州復安。", literal: "thereby Liang Province was again pacified.", idiomatic: "thereby Liang Province was again pacified." },
  { zh: "六月，己亥，封濟南簡王錯子顯為濟南王。", literal: "In the sixth month, on jihai day, Xian, son of Prince Jian of Jinan Cuo, was enfeoffed as Prince of Jinan.", idiomatic: "In the sixth month, on jihai day, Xian, son of Prince Jian of Jinan Cuo, was enfeoffed as Prince of Jinan." },
  { zh: "秋，七月，庚午，以衛尉來歷為車騎將軍。", literal: "In autumn, the seventh month, on gengwu day, Commandant of the Guards Lai Li was made General of Chariots and Cavalry.", idiomatic: "In autumn, in the seventh month, on gengwu day, Commandant of the Guards Lai Li was made General of Chariots and Cavalry." },
  { zh: "八月，鮮卑寇代郡，太守李超戰歿。", literal: "In the eighth month, the Xianbei raided Dai Commandery; Administrator Li Chao died in battle.", idiomatic: "In the eighth month the Xianbei raided Dai Commandery; Administrator Li Chao died in battle." },
  { zh: "司隸校尉虞詡到官數月，奏馮石、劉熹，免之，又劾奏中常侍程璜、陳秉、孟生、李閏等，百官側目，號為苛刻。", literal: "Director of Retainers Yu Xu, within months of taking office, memorialized against Feng Shi and Liu Xi and had them dismissed; he also impeached Palace Attendants Cheng Huang, Chen Bing, Meng Sheng, Li Run, and others—the hundred officials looked askance and called him harsh.", idiomatic: "Within months of taking office as Director of Retainers, Yu Xu memorialized against Feng Shi and Liu Xi and had them dismissed. He also impeached Palace Attendants Cheng Huang, Chen Bing, Meng Sheng, Li Run, and others. Officials looked askance and called him harsh." },
  { zh: "三公劾奏：「詡盛夏多拘繫無辜，為吏民患。", literal: "The Three Excellencies impeached: \"Xu in midsummer often imprisoned the innocent, a trouble to officials and people.", idiomatic: "The Three Excellencies impeached him: \"Xu in midsummer often imprisoned the innocent, troubling officials and people.\"" },
  { zh: "」詡上書自訟曰：「法禁者，俗之堤防；", literal: "\" Xu submitted a memorial pleading his case, saying, \"Law and prohibition are the dikes of custom;", idiomatic: "\" Xu memorialized in his own defense: \"Law and prohibition are the dikes of custom;\"" },
  { zh: "刑罰者，民之銜轡。", literal: "punishment is the bit and bridle of the people.", idiomatic: "punishment is the bit and bridle of the people.\"" },
  { zh: "今州曰任郡，郡曰任縣，更相委遠，百姓怨窮；", literal: "Now the province says it leaves matters to the commandery, the commandery says it leaves them to the county—each passes responsibility farther off, and the people are worn with resentment;", idiomatic: "Now the province leaves matters to the commandery and the commandery to the county—each passes responsibility farther off, and the people are worn with resentment;\"" },
  { zh: "以苟容為賢，盡節為愚。", literal: "to be lax and accommodating is deemed worthy, to exhaust integrity is deemed foolish.", idiomatic: "lax accommodation is deemed worthy and exhausting integrity foolish.\"" },
  { zh: "臣所發舉，臧罪非一。", literal: "Those your servant has impeached are guilty of wrongdoing more than once.", idiomatic: "Those I have impeached are guilty more than once.\"" },
  { zh: "三府恐為臣所奏，遂加誣罪。", literal: "The Three Offices fear being reported by your servant and therefore add false charges.", idiomatic: "The Three Offices fear my reports and therefore add false charges.\"" },
  { zh: "臣將從史魚死，即以尸諫耳！", literal: "Your servant will follow the death of Shi Yu and use his corpse to remonstrate!\"", idiomatic: "I will follow Shi Yu in death and use my corpse to remonstrate!\"" },
  { zh: "」帝省其章，乃不罪詡。", literal: "\" The emperor examined his memorial and did not punish Xu.", idiomatic: "\" The emperor read his memorial and did not punish Xu." },
  { zh: "中常侍張防賣弄權勢，請托受取；", literal: "Palace Attendant Zhang Fang trafficked in power, taking bribes through requests;", idiomatic: "Palace Attendant Zhang Fang trafficked in power and took bribes through patronage;" },
  { zh: "詡案之，屢寢不報。", literal: "Xu investigated him, but the cases were repeatedly shelved without response.", idiomatic: "Xu investigated him, but the cases were repeatedly shelved without response." },
  { zh: "詡不勝其憤，乃自系廷尉，奏言曰：「昔孝安皇帝任用樊豐，交亂嫡統，幾亡社稷。", literal: "Xu, unable to bear his anger, bound himself and presented himself to the Commandant of Justice, memorializing: \"In the past Emperor Xiao'an employed Fan Feng, who disturbed the legitimate succession and nearly destroyed the altars of state.", idiomatic: "Unable to bear his anger, Xu bound himself and presented himself to the Commandant of Justice, memorializing: \"In the past Emperor Xiao'an employed Fan Feng, who disturbed the legitimate succession and nearly destroyed the state.\"" },
  { zh: "今者張防復弄威柄，國家之禍將重至矣。", literal: "Now Zhang Fang again plays with the handle of power; the state's calamity is about to come again.", idiomatic: "Now Zhang Fang again wields power; the state's calamity is about to return.\"" },
  { zh: "臣不忍與防同朝，謹自系以聞，無令臣襲楊震之跡！", literal: "Your servant cannot bear to be in court with Fang and respectfully binds himself to report this—do not let your servant follow in Yang Zhen's tracks!\"", idiomatic: "I cannot bear to serve in court with Fang and respectfully bind myself to report this—do not let me follow Yang Zhen's fate!\"" },
  { zh: "」書奏，防流涕訴帝，詡坐論輸左校；", literal: "\" When the memorial was submitted, Fang wept and pleaded to the emperor; Xu was sentenced and sent to the Left Corps;", idiomatic: "\" When the memorial was submitted, Fang wept and pleaded to the emperor. Xu was sentenced and sent to the Left Corps;" },
  { zh: "防必欲害之，二日之中，傳考四獄。", literal: "Fang was determined to destroy him; within two days he was interrogated under torture in four prisons.", idiomatic: "Fang was determined to destroy him. Within two days he was tortured in four prisons." },
  { zh: "獄吏勸詡自引，詡曰：「寧伏歐刀以示遠近！", literal: "The prison clerks urged Xu to take his own life; Xu said, \"I would rather submit to the executioner's blade to show those far and near!", idiomatic: "The prison clerks urged Xu to kill himself. Xu said, \"I would rather submit to the executioner's blade to show those far and near!\"" },
  { zh: "喑嗚自殺，是非孰辨邪！", literal: "to die by secret suicide—who then could distinguish right from wrong!\"", idiomatic: "to die by secret suicide—who then could tell right from wrong?\"" },
  { zh: "」浮陽侯孫程、祝阿侯張賢相率乞見，程曰：「陛下始與臥等造事之時，常疾奸臣，知其傾國。", literal: "\" Marquis of Fuyang Sun Cheng and Marquis of Zhu'e Zhang Xian together begged audience. Cheng said, \"When Your Majesty first undertook the enterprise with us who lay in wait, you often hated treacherous ministers and knew they overturn states.", idiomatic: "\" Marquis of Fuyang Sun Cheng and Marquis of Zhu'e Zhang Xian together begged audience. Cheng said, \"When Your Majesty first undertook the enterprise with us, you hated treacherous ministers and knew they overturn states.\"" },
  { zh: "今者即位而復自為，何以非先帝乎！", literal: "Now, having taken the throne, you again act on your own—how does this differ from criticizing the former emperor!\"", idiomatic: "Now, having taken the throne, you again act on your own—how is this unlike faulting the former emperor!\"" },
  { zh: "司隸校尉虞詡為陛下盡忠，而更被拘繫；", literal: "Director of Retainers Yu Xu has exhausted loyalty for Your Majesty, yet is further imprisoned;", idiomatic: "Director of Retainers Yu Xu has been utterly loyal to Your Majesty, yet is imprisoned;\"" },
  { zh: "常侍張防臧罪明正，反構忠良。", literal: "Palace Attendant Zhang Fang's guilt is clear, yet he frames the loyal and good.", idiomatic: "Palace Attendant Zhang Fang's guilt is clear, yet he frames the loyal.\"" },
  { zh: "今客星守羽林，其占宮中有奸臣；", literal: "Now a guest star guards Yulin; its omen is that within the palace there is a treacherous minister;", idiomatic: "Now a guest star guards Yulin; its omen is a treacherous minister within the palace;\"" },
  { zh: "宜急收防送獄，以塞天變。", literal: "Your Majesty ought urgently to seize Fang and send him to prison to stem Heaven's warning.\"", idiomatic: "Your Majesty ought urgently to seize Fang and imprison him to stem Heaven's warning.\"" },
  { zh: "」時防立在帝后，程叱防曰：「奸臣張防，何不下殿！", literal: "\" At this time Fang stood behind the emperor; Cheng shouted at Fang: \"Treacherous minister Zhang Fang—why do you not leave the hall!\"", idiomatic: "\" At this time Fang stood behind the emperor. Cheng shouted at Fang: \"Treacherous minister Zhang Fang—why do you not leave the hall!\"" },
  { zh: "」防不得已，趨就東箱。", literal: "\" Fang had no choice and hurried to the eastern side chamber.", idiomatic: "\" Fang had no choice and hurried to the eastern side chamber." },
  { zh: "程曰：「陛下急收防，無令從阿母求請！", literal: "Cheng said, \"Your Majesty, urgently seize Fang—do not let him seek favor through the foster mother!\"", idiomatic: "Cheng said, \"Your Majesty, urgently seize Fang—do not let him seek favor through the foster mother!\"" },
  { zh: "」帝問諸尚書，尚書賈朗素與防善，證詡之罪；", literal: "\" The emperor asked the Masters of Writing; Master of Writing Jia Lang, who had long been friendly with Fang, attested to Xu's guilt;", idiomatic: "\" The emperor asked the Masters of Writing. Master of Writing Jia Lang, who had long been friendly with Fang, attested to Xu's guilt;" },
  { zh: "帝疑焉，謂程曰：「且出，吾方思之！", literal: "the emperor was doubtful and said to Cheng, \"Withdraw for now—I am still considering it!\"", idiomatic: "the emperor was doubtful and said to Cheng, \"Withdraw for now—I am still considering it!\"" },
  { zh: "」於是詡子顗與門生百餘人，舉幡候中常侍高梵車，叩頭流血，訴言枉狀。", literal: "\" Thereupon Xu's son Yan and more than a hundred disciples raised banners and waited for Palace Attendant Gao Fan's carriage, knocking their heads until they bled and pleading that the case was wrongful.", idiomatic: "\" Thereupon Xu's son Yan and more than a hundred disciples raised banners and waited for Palace Attendant Gao Fan's carriage, knocking their heads until they bled and pleading wrongful imprisonment." },
  { zh: "梵入言之，防坐徙邊，賈朗等六人或死或黜；", literal: "Fan entered and reported; Fang was sentenced to banishment, and Jia Lang and six others were either executed or dismissed;", idiomatic: "Fan entered and reported. Fang was banished, and Jia Lang and six others were either executed or dismissed;" },
  { zh: "即日赦出詡。", literal: "that same day Xu was pardoned and released.", idiomatic: "that same day Xu was pardoned and released." },
  { zh: "程復上書陳詡有大功，語甚切激。", literal: "Cheng again submitted a memorial stating Xu had great merit; his words were very cutting and impassioned.", idiomatic: "Cheng again memorialized that Xu had great merit; his words were very cutting." },
  { zh: "帝感悟，復徵拜議郎；", literal: "The emperor was moved to understanding and again summoned and appointed him Consultation Gentleman;", idiomatic: "The emperor was moved and again summoned him as Consultation Gentleman;" },
  { zh: "數日，遷尚書僕射。", literal: "within days he was transferred to Vice Director of the Masters of Writing.", idiomatic: "within days he was made Vice Director of the Masters of Writing." },
  { zh: "詡上疏薦議郎南陽左雄曰：「臣見方今公卿以下，類多拱默，以樹恩為賢，盡節為愚，至相戒曰：『白璧不可為，容容多後福。", literal: "Xu submitted a memorial recommending Consultation Gentleman Zuo Xiong of Nanyang: \"Your servant sees that among excellencies and ministers down, most are silent with folded hands, taking cultivation of favor as worthy and exhausting integrity as foolish—even warning one another, 'The white jade must not be touched; easy compliance brings later blessing.", idiomatic: "Xu memorialized recommending Consultation Gentleman Zuo Xiong of Nanyang: \"I see that among excellencies and ministers down, most keep silent, taking cultivation of favor as worthy and exhausting integrity as foolish—even warning one another, 'Do not touch white jade; easy compliance brings later blessing.\"" },
  { zh: "』伏見議郎左雄，有王臣蹇蹇之節，宜擢在喉舌之官，必有國弼之益。", literal: "' Your servant has observed Consultation Gentleman Zuo Xiong, who has the upright integrity of a king's minister; he ought to be promoted to a throat-and-tongue office and will surely benefit the state as a buttress.\"", idiomatic: "' I observe Consultation Gentleman Zuo Xiong, who has a king's minister's upright integrity; he ought to be promoted to a speaking office and will surely buttress the state.\"" },
  { zh: "」由是拜雄尚書。", literal: "\" Thereupon Xiong was appointed Master of Writing.", idiomatic: "\" Thereupon Xiong was appointed Master of Writing." },
  { zh: "浮陽侯孫程等懷表上殿爭功，帝怒。", literal: "Marquis of Fuyang Sun Cheng and others, bearing memorials, went up to the hall to dispute merit; the emperor was angry.", idiomatic: "Marquis of Fuyang Sun Cheng and others went up to the hall bearing memorials to dispute merit; the emperor was angry." },
  { zh: "有司劾奏「程等於亂悖逆，王國等皆與程黨，久留京都，益其驕恣。", literal: "The responsible officials impeached: \"Cheng and others were disorderly and rebellious; Wang Guo and the rest are all Cheng's faction, long remaining in the capital and increasing their arrogance.", idiomatic: "The responsible officials impeached: \"Cheng and others were disorderly and rebellious; Wang Guo and the rest are all Cheng's faction, long remaining in the capital and growing more arrogant.\"" },
  { zh: "」帝乃免程等官，悉徙封遠縣。", literal: "\" The emperor then dismissed Cheng and the rest from office and all transferred their enfeoffments to distant counties.", idiomatic: "\" The emperor then dismissed Cheng and the rest from office and transferred all their enfeoffments to distant counties." },
  { zh: "因遺十九侯就國，敕洛陽令促期發遺。", literal: "Thereupon he sent the nineteen marquises to their states and ordered the magistrate of Luoyang to hasten their departure on schedule.", idiomatic: "He then sent the nineteen marquises to their states and ordered the magistrate of Luoyang to hasten their departure." },
  { zh: "司徒掾周舉說朱倀曰：「朝廷在西鐘下時，非孫程等豈立！", literal: "A clerk of the Minister over the Masses, Zhou Ju, urged Zhu Yi: \"When the court was below the west bell, without Sun Cheng and the rest, how could Your Majesty have been established!", idiomatic: "Minister over the Masses clerk Zhou Ju urged Zhu Yi: \"When the court was below the west bell, without Sun Cheng and the rest how could Your Majesty have been established!\"" },
  { zh: "今忘其大德，錄其小過。", literal: "Now you forget their great merit and record their small faults.", idiomatic: "Now you forget their great merit and record their small faults.\"" },
  { zh: "如道路夭折，帝有殺功臣之譏。", literal: "If they die on the road prematurely, Your Majesty will bear the reproach of killing meritorious servants.", idiomatic: "If they die on the road, Your Majesty will bear the reproach of killing meritorious servants.\"" },
  { zh: "及今未去，宜急表之！", literal: "While they have not yet gone, you ought urgently to memorialize!\"", idiomatic: "While they have not yet gone, you ought urgently to memorialize!\"" },
  { zh: "倀曰：「今詔指方怒，吾獨表此，必致罪譴。", literal: "Yi said, \"The edict's intent is now angry; if I alone memorialize this, I am sure to incur punishment.", idiomatic: "Yi said, \"The edict's intent is angry now; if I alone memorialize this I am sure to be punished.\"" },
  { zh: "」舉曰：「明公年過八十，位為台輔，不於今時竭忠報國，惜身安，欲以何求！", literal: "\" Ju said, \"Your Excellency is past eighty and holds terrace and chariot rank—if not at this time you exhaust loyalty and serve the state, cherishing your person in safety, what do you seek!\"", idiomatic: "\" Ju said, \"Your Excellency is past eighty and holds the highest rank—if not now you exhaust loyalty and serve the state, cherishing safety, what do you seek!\"" },
  { zh: "祿位雖全，必陷佞邪之機；", literal: "Though salary and rank are preserved, you will surely fall into the snare of flattery and wickedness;", idiomatic: "Though salary and rank are preserved, you will fall into flattery and wickedness;\"" },
  { zh: "諫而獲罪，猶有忠貞之名。", literal: "to remonstrate and receive punishment still leaves the name of loyalty and integrity.", idiomatic: "to remonstrate and be punished still leaves a name for loyalty.\"" },
  { zh: "若舉言不足采，請從此辭！", literal: "If Your Excellency's words are not worth adopting, I beg to take leave from here!\"", idiomatic: "If my words are not worth adopting, I beg to take my leave!\"" },
  { zh: "」倀乃表諫，帝果從之。", literal: "\" Yi then memorialized in remonstrance, and the emperor indeed followed it.", idiomatic: "\" Yi then memorialized in remonstrance, and the emperor followed it." },
  { zh: "程徙封宜城侯，到國，怨恨恚懟，封還印綬、符策，亡歸京師，往來山中。", literal: "Cheng was transferred and enfeoffed as Marquis of Yicheng; reaching his state, resentful and indignant, he sealed and returned seal and ribbon, tally and patent, fled back to the capital, and went to and fro in the mountains.", idiomatic: "Cheng was transferred to Marquis of Yicheng. Reaching his state, resentful and indignant, he returned seal, ribbon, tally, and patent, fled back to the capital, and wandered in the mountains." },
  { zh: "詔書追求，復故爵土，賜車馬、衣物，遣還國。", literal: "An edict pursued him; his former rank and fief were restored, carriage, horses, and clothing were bestowed, and he was sent back to his state.", idiomatic: "An edict pursued him, restored his former rank and fief, bestowed carriage, horses, and clothing, and sent him back to his state." },
  { zh: "冬，十月，丁亥，司空陶敦免。", literal: "In winter, the tenth month, on dinghai day, Minister of Works Tao Dun was dismissed.", idiomatic: "In winter, in the tenth month, on dinghai day, Minister of Works Tao Dun was dismissed." },
  { zh: "朔方以西，障塞多壞，鮮卑因此數侵南匈奴；", literal: "West of Shuofang, many border barriers were ruined, and the Xianbei therefore several times raided the Southern Xiongnu;", idiomatic: "West of Shuofang many border barriers were ruined, and the Xianbei therefore repeatedly raided the Southern Xiongnu;" },
  { zh: "單于憂恐，上書乞修復障塞。", literal: "the chanyu was anxious and fearful and submitted a memorial begging repair of the barriers.", idiomatic: "the chanyu was anxious and memorialized begging repair of the barriers." },
  { zh: "庚寅，詔：「黎陽營兵出屯中山北界；", literal: "On gengyin day, an edict: \"Troops of the Liyang camp shall go out and garrison the northern border of Zhongshan;", idiomatic: "On gengyin day an edict ordered: \"Troops of the Liyang camp shall garrison the northern border of Zhongshan;\"" },
  { zh: "令緣邊郡增置步兵，列屯塞下，教習戰射。", literal: "order the border commanderies to add foot soldiers, array them in garrison below the passes, and teach battle and archery.\"", idiomatic: "order the border commanderies to add foot soldiers, garrison them below the passes, and teach battle and archery.\"" },
  { zh: "以廷尉張皓為司空。", literal: "Commandant of Justice Zhang Hao was made Minister of Works.", idiomatic: "Commandant of Justice Zhang Hao was made Minister of Works." },
  { zh: "班勇更立車師後部故王子加特奴為王。", literal: "Ban Yong again established the former prince of the Rear Kingdom of Cheshi, Jianute, as king.", idiomatic: "Ban Yong again established the former prince of the Rear Kingdom of Cheshi, Jianute, as king." },
  { zh: "勇又使別校誅斬東且彌王，亦更立其種人為王；", literal: "Yong also sent a separate colonel to execute the king of Eastern Qumi and again established a man of that tribe as king;", idiomatic: "Yong also sent a separate colonel to execute the king of Eastern Qumi and again established a tribesman as king;" },
  { zh: "於是車師六國悉平。", literal: "thereupon the six states of Cheshi were all pacified.", idiomatic: "thereby the six states of Cheshi were all pacified." },
  { zh: "勇遂發諸國兵擊匈奴，呼銜王亡走，其眾二萬餘人皆降。", literal: "Yong then mobilized the armies of the various states to attack the Xiongnu; King Huyan fled, and his masses of more than twenty thousand all submitted.", idiomatic: "Yong then mobilized the armies of the various states against the Xiongnu. King Huyan fled and more than twenty thousand of his followers submitted." },
  { zh: "生得單于人兄，勇使加特奴手斬之，以結車師、匈奴之隙。", literal: "They captured the chanyu's elder brother alive; Yong had Jianute personally behead him to seal the breach between Cheshi and the Xiongnu.", idiomatic: "They captured the chanyu's elder brother alive. Yong had Jianute personally behead him to seal the breach between Cheshi and the Xiongnu." },
  { zh: "北單于自將萬餘騎入後部，至金且谷；", literal: "The Northern Chanyu himself led more than ten thousand horsemen into the Rear Kingdom as far as Jinqie Valley;", idiomatic: "The Northern Chanyu himself led more than ten thousand horsemen into the rear kingdom as far as Jinqie Valley;" },
  { zh: "勇使假司馬曹俊救之，單于引去，俊追斬其貴人骨都侯。", literal: "Yong sent Acting Major Cao Jun to rescue them; the chanyu withdrew, and Jun pursued and beheaded his noble Guduhou.", idiomatic: "Yong sent Acting Major Cao Jun to rescue them. The chanyu withdrew and Jun pursued and killed his noble Guduhou." },
  { zh: "於是呼衍王遂徙居枯梧河上，是後車師無復虜跡。", literal: "Thereupon King Huyan moved to dwell on the Kuwu River, and after this Cheshi had no further traces of barbarians.", idiomatic: "Thereupon King Huyan moved to the Kuwu River, and afterward Cheshi saw no further barbarian presence." },
  { zh: "春，正月，中郎將張國以南單于兵擊鮮卑其至鞬，破之。", literal: "In spring, the first month, Colonel of the Gentlemen Zhang Guo with the Southern Chanyu's troops attacked the Xianbei Qizhijian and defeated them.", idiomatic: "In spring, in the first month, Colonel Zhang Guo with the Southern Chanyu's troops attacked the Xianbei Qizhijian and defeated them." },
  { zh: "二月，遼東鮮卑寇遼東玄菟；", literal: "In the second month, the Liaodong Xianbei raided Liaodong and Xuantu;", idiomatic: "In the second month the Liaodong Xianbei raided Liaodong and Xuantu;" },
  { zh: "烏桓校尉耿曄發緣邊諸郡兵及烏桓出塞擊之，斬獲甚眾；", literal: "Colonel of the Wuhuan Geng Ye mobilized border commandery troops and the Wuhuan beyond the pass to strike them, beheading and capturing a great host;", idiomatic: "Colonel of the Wuhuan Geng Ye mobilized border commandery troops and the Wuhuan beyond the pass to strike them, taking many heads and captives;" },
  { zh: "鮮卑三萬人詣遼東降。", literal: "thirty thousand Xianbei came to Liaodong to submit.", idiomatic: "and thirty thousand Xianbei came to Liaodong to submit." },
  { zh: "三月，旱。", literal: "In the third month, there was drought.", idiomatic: "In the third month there was drought." },
  { zh: "初，帝母李氏瘞在洛陽北，帝初不知；", literal: "Earlier, the emperor's mother Lady Li was buried in the north of Luoyang, and at first the emperor did not know;", idiomatic: "Earlier, the emperor's mother Lady Li was buried north of Luoyang, and at first the emperor did not know;" },
  { zh: "至是，左右白之，帝乃發哀，親到瘞所，更以禮殯。", literal: "at this time those about him informed him; the emperor then expressed mourning, went in person to the burial place, and again interred her with full rites.", idiomatic: "at this time those about him informed him. The emperor then expressed mourning, went in person to the burial place, and again interred her with full rites." },
  { zh: "六月，乙酉，追謚為恭愍皇后，葬於恭陵之北。", literal: "In the sixth month, on yiyou, she was posthumously titled Empress Gongmin and buried north of Gong Mausoleum.", idiomatic: "In the sixth month, on yiyou day, she was posthumously titled Empress Gongmin and buried north of Gong Mausoleum." },
  { zh: "西域城郭諸國皆服於漢，唯焉耆王元孟未降，班勇奏請攻之。", literal: "The walled states of the Western Regions all submitted to Han; only King Yuan Meng of Yanqi had not submitted, and Ban Yong memorialized requesting an attack.", idiomatic: "The walled states of the Western Regions all submitted to Han; only King Yuan Meng of Yanqi had not submitted, and Ban Yong memorialized requesting an attack." },
  { zh: "於是遣敦煌太守張朗將河西四郡兵三千人配勇，因發諸國兵四萬餘人分為兩道擊之。", literal: "Thereupon Administrator of Dunhuang Zhang Lang was sent to lead three thousand troops of the four Hexi commanderies to join Yong, and troops of the various states totaling more than forty thousand were mobilized and divided into two columns to attack.", idiomatic: "Thereupon Administrator of Dunhuang Zhang Lang was sent to lead three thousand troops of the four Hexi commanderies to join Ban Yong, and troops of the various states totaling more than forty thousand were mobilized and divided into two columns to attack." },
  { zh: "勇從南道，朗從北道，約期俱至焉耆。", literal: "Yong took the southern route, Lang the northern, agreeing to arrive at Yanqi together on a set date.", idiomatic: "Ban Yong took the southern route and Zhang Lang the northern, agreeing to arrive at Yanqi together on a set date." },
  { zh: "而朗先有罪，欲徼功自贖，遂先期至爵離關，遣司馬將兵前戰，獲首虜二千餘人，元孟懼誅，逆遣使乞降。", literal: "But Lang had earlier committed a crime and wished to win merit to redeem himself; he therefore arrived ahead of schedule at Jueli Pass, sent his Major with troops to fight in advance, and obtained more than two thousand heads and captives; Yuan Meng feared execution and beforehand sent envoys to beg submission.", idiomatic: "But Zhang Lang had earlier committed a crime and wished to win merit to redeem himself. He therefore arrived ahead of schedule at Jueli Pass, sent his Major with troops to fight in advance, and took more than two thousand heads and captives. Yuan Meng feared execution and beforehand sent envoys to beg submission." },
  { zh: "張朗徑入焉耆，受降而還。", literal: "Zhang Lang went straight into Yanqi, accepted the surrender, and returned.", idiomatic: "Zhang Lang went straight into Yanqi, accepted the surrender, and returned." },
  { zh: "朗得免誅，勇以後期徵，下獄，免。", literal: "Lang was spared execution; Yong was summoned for being late, imprisoned, and dismissed.", idiomatic: "Zhang Lang was spared execution. Ban Yong was summoned for being late, imprisoned, and dismissed." },
  { zh: "秋，七月，甲戌朔，日有食之。", literal: "In autumn, the seventh month, on the first day jiaxu, there was a solar eclipse.", idiomatic: "In autumn, in the seventh month, on the first day jiaxu, there was a solar eclipse." },
  { zh: "壬午，太尉朱寵、司徒朱倀免。", literal: "On renwu, Grand Commandant Zhu Chong and Minister over the Masses Zhu Yi were dismissed.", idiomatic: "On renwu day, Grand Commandant Zhu Chong and Minister over the Masses Zhu Yi were dismissed." },
  { zh: "庚子，以太常劉光為太尉、錄尚書事，光祿勳汝南許敬為司徒。", literal: "On gengzi, Grand Master of Ceremonies Liu Guang was made Grand Commandant and Recorder of Matters Relating to the Masters of Writing; Household Minister Xu Jing of Runan was made Minister over the Masses.", idiomatic: "On gengzi day, Grand Master of Ceremonies Liu Guang was made Grand Commandant and Recorder of Matters Relating to the Masters of Writing, and Household Minister Xu Jing of Runan was made Minister over the Masses." },
  { zh: "光，矩之弟也。", literal: "Guang was the younger brother of Ju.", idiomatic: "Liu Guang was the younger brother of Liu Ju." },
  { zh: "敬仕於和、安之間，當竇、鄧、閻氏之盛，無所屈撓；", literal: "Jing served between the He and An reigns, when the Dou, Deng, and Yan clans were at their height, yet he bent to none;", idiomatic: "Xu Jing served between the He and An reigns, when the Dou, Deng, and Yan clans were at their height, yet he bent to none;" },
  { zh: "三家既敗，士大夫多染污者，獨無謗言及於敬，當世以此貴之。", literal: "after the three houses had fallen many scholar-officials were stained, yet no slander reached Jing, and the age for this held him in honor.", idiomatic: "after the three houses had fallen many scholar-officials were stained, yet no slander reached Xu Jing, and the age for this held him in honor." },
  { zh: "初，南陽樊英，少有學行，名著海內，陷於壺山之陽，州郡前後禮請，不應；", literal: "Earlier, Fan Ying of Nanyang from youth had learning and conduct, his fame known within the seas; he dwelt on the southern slope of Mount Hu, and though provinces and commanderies repeatedly invited him with ceremony, he did not respond;", idiomatic: "Earlier, Fan Ying of Nanyang from youth had learning and conduct and his fame was known within the seas. He dwelt on the southern slope of Mount Hu, and though provinces and commanderies repeatedly invited him with ceremony, he did not respond;" },
  { zh: "公卿舉賢良、方正、有道，皆不行；", literal: "the dukes and ministers recommended him as Worthy, Upright, and Possessed of the Way, yet he would not go;", idiomatic: "the dukes and ministers recommended him as Worthy, Upright, and Possessed of the Way, yet he would not go;" },
  { zh: "安帝賜策書徵之，不赴。", literal: "Emperor An bestowed a written summons and called him, but he did not come.", idiomatic: "Emperor An bestowed a written summons and called him, but he did not come." },
  { zh: "是歲，帝復以策書、玄纁，備禮徵英，英固辭疾篤。", literal: "That year the emperor again with written summons and black-and-red silks, with full ceremony summoned Ying; Ying firmly pleaded grave illness.", idiomatic: "That year the emperor again summoned Fan Ying with written summons and black-and-red silks and full ceremony, but Ying firmly pleaded grave illness." },
  { zh: "詔切責郡縣，駕載上道。", literal: "An edict sharply reproved the commanderies and counties, and he was carried in a carriage onto the road.", idiomatic: "An edict sharply reproved the commanderies and counties, and he was carried in a carriage onto the road." },
  { zh: "英不得已，到京，稱疾不肯起；", literal: "Ying had no choice but to arrive at the capital, claimed illness and would not rise;", idiomatic: "Fan Ying had no choice but to arrive at the capital, claimed illness, and would not rise;" },
  { zh: "強輿入殿，猶不能屈。", literal: "he was forcibly carried into the hall, yet still could not be bent.", idiomatic: "he was forcibly carried into the hall, yet still could not be bent." },
  { zh: "帝使出就太醫養疾，月致羊酒。", literal: "The emperor had him go out to the Imperial Physician to nurse his illness, and each month sent mutton and wine.", idiomatic: "The emperor had him go out to the Imperial Physician to nurse his illness, and each month sent mutton and wine." },
  { zh: "其後帝乃為英設壇，令公車令導，尚書奉引，賜幾、杖，待以師傅之禮，延問得失，拜五官中郎將。", literal: "Afterward the emperor then set up an altar for Ying, ordered the Director of the Imperial Carriages to lead, the Masters of Writing to attend and conduct, bestowed a armrest and staff, treated him with the rites due a tutor, extended inquiry into gains and losses, and appointed him Colonel of the Five Offices.", idiomatic: "Afterward the emperor set up an altar for Fan Ying, ordered the Director of the Imperial Carriages to lead and the Masters of Writing to attend and conduct, bestowed an armrest and staff, treated him with the rites due a tutor, extended inquiry into gains and losses, and appointed him Colonel of the Five Offices." },
  { zh: "數月，英稱疾篤；", literal: "After several months Ying claimed grave illness;", idiomatic: "After several months Fan Ying claimed grave illness;" },
  { zh: "詔以為光祿大夫，賜告歸，令在所送谷，以歲時致牛酒。", literal: "an edict made him Household Minister, granted leave to return home, ordered the locality to send grain, and at the seasons to deliver oxen and wine.", idiomatic: "an edict made him Household Minister, granted leave to return home, ordered the locality to send grain, and at the seasons to deliver oxen and wine." },
  { zh: "英辭位不受，有詔譬旨，勿聽。", literal: "Ying declined the rank and would not accept; an edict explained the intent and forbade refusal.", idiomatic: "Fan Ying declined the rank and would not accept. An edict explained the intent and forbade refusal." },
  { zh: "英初被詔命，眾皆以為必不降志。", literal: "When Ying was first under the imperial summons, the multitude all thought he would surely not lower his resolve.", idiomatic: "When Fan Ying was first under the imperial summons, the multitude all thought he would surely not lower his resolve." },
  { zh: "南郡王逸素與英善，因與其書，多引古譬諭，勸使就聘。", literal: "Wang Yi of Nan commandery had long been friendly with Ying and therefore wrote him a letter with many ancient analogies and persuasions, urging him to accept the appointment.", idiomatic: "Wang Yi of Nan commandery had long been friendly with Fan Ying and therefore wrote him a letter with many ancient analogies and persuasions, urging him to accept the appointment." },
  { zh: "英順逸議而至；", literal: "Ying followed Yi's counsel and came;", idiomatic: "Fan Ying followed Wang Yi's counsel and came;" },
  { zh: "及後應對無奇謀深策，談者以為失望。", literal: "but afterward in his responses there were no extraordinary plans or deep policies, and those who discussed it felt disappointment.", idiomatic: "but afterward in his responses there were no extraordinary plans or deep policies, and those who discussed it felt disappointment." },
  { zh: "河南張楷與英俱徵，謂英曰：「天下有二道，出與處也。", literal: "Zhang Kai of Henan was summoned together with Ying and said to Ying: \"All under heaven has two paths—going forth and staying put.", idiomatic: "Zhang Kai of Henan was summoned together with Fan Ying and said to him, \"All under heaven has two paths—going forth and staying put." },
  { zh: "吾前以子之出，能輔是君也，濟斯民也。", literal: "I formerly thought that in your going forth you could assist this ruler and succor these people.", idiomatic: "I formerly thought that in your going forth you could assist this ruler and succor these people." },
  { zh: "而子始以不訾之身，怒萬乘之主，及其享受爵祿，又不聞匡救之術，進退無所據矣。", literal: "Yet you first with an unblemished person angered a ruler of ten thousand chariots, and once you enjoyed rank and salary you were not heard to have methods of correction and rescue—going forth and staying put have no footing left.\"", idiomatic: "Yet you first with an unblemished person angered a ruler of ten thousand chariots, and once you enjoyed rank and salary you were not heard to have methods of correction and rescue—going forth and staying put have no footing left.\"" },
  { zh: "臣光曰：古之君子，邦有道則仕，邦無道則隱。", literal: "Subject Guang said: The gentleman of old, when the state had the Way then served; when the state lacked the Way then hid.", idiomatic: "Sima Guang remarks: The gentleman of old, when the state had the Way then served; when the state lacked the Way then hid." },
  { zh: "隱非君子之所欲也。", literal: "Hiding was not what the gentleman desired.", idiomatic: "Hiding was not what the gentleman desired." },
  { zh: "人莫己知而道不得行，群邪共處而害將及身，故深藏以避之。", literal: "No one knew him yet the Way could not be practiced; the wicked dwelt together and harm was about to reach his person—therefore he hid deep to avoid it.", idiomatic: "No one knew him yet the Way could not be practiced; the wicked dwelt together and harm was about to reach his person—therefore he hid deep to avoid it." },
  { zh: "王者舉逸民，揚仄陋，固為其有益於國家，非以徇世俗之耳目也。", literal: "When kings raised reclusive subjects and exalted the obscure and lowly, it was truly because they benefited the state, not to please the eyes and ears of the vulgar world.", idiomatic: "When kings raised reclusive subjects and exalted the obscure and lowly, it was truly because they benefited the state, not to please the eyes and ears of the vulgar world." },
  { zh: "是故有道德足以尊主，智能足以庇民，被褐懷玉，深藏不市，則王者當盡禮以致之，屈體以下之，虛心以訪之，克己以從之，然後能利澤施於四表，功烈格於上下。", literal: "Therefore if moral power was enough to honor the ruler and wisdom enough to shelter the people, wearing coarse cloth yet cherishing jade, hiding deep and not offering himself for sale—then the king ought with full rites to bring him, bow the body to descend to him, empty the mind to consult him, restrain the self to follow him—only then could benefit and grace spread to the four quarters and merit and glory reach above and below.", idiomatic: "Therefore if moral power was enough to honor the ruler and wisdom enough to shelter the people, wearing coarse cloth yet cherishing jade, hiding deep and not offering himself for sale—then the king ought with full rites to bring him, bow the body to descend to him, empty the mind to consult him, and restrain the self to follow him—only then could benefit and grace spread to the four quarters and merit and glory reach above and below." },
  { zh: "蓋取其道不取其人，務其實不務其名也。", literal: "This was taking his Way, not taking the man; seeking the substance, not seeking the name.", idiomatic: "This was taking his Way, not taking the man; seeking the substance, not seeking the name." },
  { zh: "其或禮備而不至，意勤而不起，則姑內自循省而不敢強致其人，曰：豈吾德之薄而不足慕乎？", literal: "If rites were complete yet he did not come, intent earnest yet he did not rise—then for the moment he turned inward to examine himself and did not dare force the man, saying: Is my virtue thin and not worth esteeming?", idiomatic: "If rites were complete yet he did not come, intent earnest yet he did not rise—then for the moment he turned inward to examine himself and did not dare force the man, saying, Is my virtue thin and not worth esteeming?" },
  { zh: "政之亂而不可輔乎？", literal: "Is government chaotic and not to be assisted?", idiomatic: "Is government chaotic and not to be assisted?" },
  { zh: "群小在朝而不敢進乎？", literal: "Are petty men in court and one dares not advance?", idiomatic: "Are petty men in court and one dares not advance?" },
  { zh: "誠心不至而憂其言之不用乎？", literal: "Is sincere heart not arrived and one fears his words will not be used?", idiomatic: "Is sincere heart not arrived and one fears his words will not be used?" },
  { zh: "何賢者之不我從也？", literal: "Why do the worthy not follow me?", idiomatic: "Why do the worthy not follow me?" },
  { zh: "苟其德已厚矣，政已治矣，群小遠矣，誠心至矣，彼將扣閽以自售，又安有勤求而不至者哉！", literal: "If his virtue were already thick, government already ordered, petty men far off, sincere heart arrived—then they would knock at the gate to offer themselves; how could there be earnest seeking yet failure to come!", idiomatic: "If his virtue were already thick, government already ordered, petty men far off, and sincere heart arrived—then they would knock at the gate to offer themselves. How could there be earnest seeking yet failure to come!" },
  { zh: "荀子曰：「耀蟬者，務在明其火，振其木而已；", literal: "Xunzi said: \"One who gathers cicadas with fire must make the fire bright and shake the tree—that is all;\"", idiomatic: "Xunzi said, \"One who gathers cicadas with fire must make the fire bright and shake the tree—that is all;\"" },
  { zh: "火不明，雖振其木，無益也。", literal: "\"if the fire is not bright, though one shakes the tree, it is of no use.", idiomatic: "\"if the fire is not bright, though one shakes the tree, it is of no use." },
  { zh: "今人主有能明其德，則天下歸之，若蟬之歸明火也。", literal: "If today's ruler can make his virtue bright, then all under heaven will come to him, as cicadas come to bright fire.\"", idiomatic: "If today's ruler can make his virtue bright, then all under heaven will come to him, as cicadas come to bright fire.\"" },
  { zh: "」或者人主恥不能致，乃至誘之以高位，脅之以嚴刑。", literal: "\" Some rulers, shamed that they cannot bring men, even entice them with high rank and threaten them with severe punishment.", idiomatic: "\" Some rulers, shamed that they cannot bring men, even entice them with high rank and threaten them with severe punishment." },
  { zh: "使彼誠君子邪，則位非所貪，刑非所畏，終不可得而致也；", literal: "If they were truly gentlemen, then rank is not what they covet and punishment not what they fear—in the end they cannot be brought;", idiomatic: "If they were truly gentlemen, then rank is not what they covet and punishment not what they fear—in the end they cannot be brought;" },
  { zh: "可致者，皆貪位畏刑之人也，烏足貴哉！", literal: "those who can be brought are all men who covet rank and fear punishment—how are they worth honoring!", idiomatic: "those who can be brought are all men who covet rank and fear punishment—how are they worth honoring!" },
  { zh: "若乃孝弟著於家庭，行誼隆於鄉曲，利不苟取，仕不苟進，潔己安分，優遊卒歲，雖不足以尊主庇民，是亦清修之吉士也。", literal: "As for those whose filial piety and brotherliness shine in the family and whose conduct and righteousness rise in the village lanes, who do not grasp profit at random or advance in office at random, who keep themselves pure and rest in their lot, passing the year at ease—though not enough to honor the ruler and shelter the people, these too are auspicious gentlemen of pure cultivation.", idiomatic: "As for those whose filial piety and brotherliness shine in the family and whose conduct and righteousness rise in the village lanes, who do not grasp profit at random or advance in office at random, who keep themselves pure and rest in their lot, passing the year at ease—though not enough to honor the ruler and shelter the people, these too are auspicious gentlemen of pure cultivation." },
  { zh: "王者當褒優安養，俾遂其志。", literal: "Kings ought to praise, favor, settle, and nurture them, enabling them to fulfill their intent.", idiomatic: "Kings ought to praise, favor, settle, and nurture them, enabling them to fulfill their intent." },
  { zh: "若孝昭之待韓福，光武之遇周黨，以勵廉恥，美風俗，斯亦可矣，固不當如范升之詆毀，又不可如張楷之責望也。", literal: "Like Emperor Xiaozhao's treatment of Han Fu or Emperor Guangwu's meeting with Zhou Dang—to encourage integrity and shame and beautify custom—this too is fitting; one certainly should not, like Fan Sheng, slander them, nor, like Zhang Kai, press demands upon them.", idiomatic: "Like Emperor Xiaozhao's treatment of Han Fu or Emperor Guangwu's meeting with Zhou Dang—to encourage integrity and shame and beautify custom—this too is fitting. One certainly should not, like Fan Sheng, slander them, nor, like Zhang Kai, press demands upon them." },
  { zh: "至於飾偽以邀譽，釣奇以驚俗，不食君祿而爭屠沽之利，不受小官而規卿相之位，名與實反，心與跡違，斯乃華士、少正卯之流，其得免於聖王之誅幸矣，尚何聘召之有哉！", literal: "As for those who adorn falsehood to win praise, angle for the strange to startle the vulgar, refuse the ruler's salary yet contend for the butcher's and peddler's profit, decline petty office yet scheme for minister and chancellor rank—name and substance opposed, heart and tracks at odds—these are the sort of flashy gentlemen and Shao Zheng Mao; that they escape the sage king's punishment is already fortunate—how much less any summons to office!", idiomatic: "As for those who adorn falsehood to win praise, angle for the strange to startle the vulgar, refuse the ruler's salary yet contend for the butcher's and peddler's profit, decline petty office yet scheme for minister and chancellor rank—name and substance opposed, heart and tracks at odds—these are the sort of flashy gentlemen and Shao Zheng Mao. That they escape the sage king's punishment is already fortunate—how much less any summons to office!" },
  { zh: "時又徵廣漢楊厚、江夏黃瓊。", literal: "At this time Yang Hou of Guanghan and Huang Qiong of Jiangxia were also summoned.", idiomatic: "At this time Yang Hou of Guanghan and Huang Qiong of Jiangxia were also summoned." },
  { zh: "瓊，香之子也。", literal: "Qiong was the son of Xiang.", idiomatic: "Huang Qiong was the son of Huang Xiang." },
  { zh: "厚既至，豫陳漢有三百五十年之厄以為戒，拜議郎。", literal: "When Hou had arrived he beforehand set forth that Han would have a calamity at three hundred fifty years as a warning, and was appointed Gentleman Consultant.", idiomatic: "When Yang Hou had arrived he beforehand set forth that Han would have a calamity at three hundred fifty years as a warning, and was appointed Gentleman Consultant." },
  { zh: "瓊將至，李固以書逆遺之曰：「君子謂伯夷隘，柳下惠不恭。", literal: "As Qiong was about to arrive, Li Gu with a letter went to meet and present it to him, saying: \"The gentleman says Boyi was narrow and Liuxia Hui was not respectful.", idiomatic: "As Huang Qiong was about to arrive, Li Gu with a letter went to meet and present it to him, saying, \"The gentleman says Boyi was narrow and Liuxia Hui was not respectful." },
  { zh: "不夷不惠，可否之間，聖賢居身之所珍也。", literal: "Neither narrow nor disrespectful, in the interval of yes and no—this is what sages and worthies treasure in placing themselves.", idiomatic: "Neither narrow nor disrespectful, in the interval of yes and no—this is what sages and worthies treasure in placing themselves." },
  { zh: "誠遂欲枕山棲谷，擬跡巢、由，斯則可矣；", literal: "If you truly wish to pillow the mountains and nest in valleys, taking as model the tracks of Chao and You, that may do;", idiomatic: "If you truly wish to pillow the mountains and nest in valleys, taking as model the tracks of Chao and You, that may do;" },
  { zh: "若當輔政濟民，今其時也。", literal: "if you ought to assist government and succor the people, now is the time.", idiomatic: "if you ought to assist government and succor the people, now is the time." },
  { zh: "自生民以來，善政少而亂俗多，必待堯、舜之君，此為士行其志終無時矣。", literal: "From the birth of the people, good government has been few and chaotic custom many; to insist on waiting for rulers like Yao and Shun—then for scholars to practice their intent there will never be a time.", idiomatic: "From the birth of the people, good government has been few and chaotic custom many. To insist on waiting for rulers like Yao and Shun—then for scholars to practice their intent there will never be a time." },
  { zh: "常聞語曰：『嶢嶢者易缺，皦皦者易污。", literal: "I have often heard the saying: 'The towering is easily broken; the dazzling is easily stained.", idiomatic: "I have often heard the saying, 'The towering is easily broken; the dazzling is easily stained." },
  { zh: "』盛名之下，其實難副。", literal: "' Under great fame, the substance is hard to match.", idiomatic: "' Under great fame, the substance is hard to match." },
  { zh: "近魯陽樊君被徵，初至，朝廷設壇席，猶待神明，雖無大異，而言行所守，亦無所缺；", literal: "Recently the Master of Luyang, Fan, was summoned; when he first arrived the court set up altar and mat as if awaiting a spirit. Though there was no great difference, in word and conduct what he upheld was not lacking;", idiomatic: "Recently the Master of Luyang, Fan Ying, was summoned. When he first arrived the court set up altar and mat as if awaiting a spirit. Though there was no great difference, in word and conduct what he upheld was not lacking;" },
  { zh: "而毀謗布流，應時折減者，豈非觀聽望深，聲名太盛乎！", literal: "yet slander spread abroad and he was at once diminished—is it not because what observers hoped for was deep and his fame too great!", idiomatic: "yet slander spread abroad and he was at once diminished—is it not because what observers hoped for was deep and his fame too great!" },
  { zh: "是故俗論皆言『處士純盜虛聲』。", literal: "Therefore vulgar opinion all says 'recluses purely steal empty fame.'", idiomatic: "Therefore vulgar opinion all says 'recluses purely steal empty fame.'" },
  { zh: "願先生弘此遠謨，令眾人歎服，一雪此言耳！", literal: "I wish you, sir, would expand this far-reaching plan, make the multitude sigh in admiration, and once wash away this saying!", idiomatic: "I wish you, sir, would expand this far-reaching plan, make the multitude sigh in admiration, and once wash away this saying!" },
  { zh: "」瓊至，拜議郎，稍遷尚書僕射。", literal: "\" When Qiong arrived he was appointed Gentleman Consultant and was gradually promoted to Vice Director of the Masters of Writing.", idiomatic: "\" When Huang Qiong arrived he was appointed Gentleman Consultant and was gradually promoted to Vice Director of the Masters of Writing." },
  { zh: "瓊昔隨父在台閣，習見故事；", literal: "Qiong had formerly followed his father in the terrace offices and was practiced in precedents;", idiomatic: "Huang Qiong had formerly followed his father in the terrace offices and was practiced in precedents;" },
  { zh: "及後居職，達練官曹，爭議朝堂，莫能抗奪。", literal: "when he later held office he was thoroughly versed in the bureaus; in debate at court none could withstand or overturn him.", idiomatic: "when he later held office he was thoroughly versed in the bureaus. In debate at court none could withstand or overturn him." },
  { zh: "數上疏言事，上頗採用之。", literal: "He several times submitted memorials on affairs, and the emperor quite adopted his proposals.", idiomatic: "He several times submitted memorials on affairs, and the emperor quite adopted his proposals." },
  { zh: "李固，郃之子，少好學，常改易姓名，杖策驅驢，負笈從師，不遠千里，遂究覽墳籍，為世大儒。", literal: "Li Gu was the son of He; from youth he loved learning, often changed his name, staff in hand drove a donkey, carried a book box to follow teachers—not shrinking from a thousand li—and thus thoroughly perused the classics, becoming a great Confucian of the age.", idiomatic: "Li Gu was the son of Li He. From youth he loved learning, often changed his name, staff in hand drove a donkey, and carried a book box to follow teachers—not shrinking from a thousand li—and thus thoroughly perused the classics, becoming a great Confucian of the age." },
  { zh: "每到太學，密入公府，定省父母，不令同業諸生知其為郃子也。", literal: "Whenever he reached the Imperial Academy he would secretly enter his father's offices to attend his parents morning and evening, not letting fellow students know he was He's son.", idiomatic: "Whenever he reached the Imperial Academy he would secretly enter his father's offices to attend his parents morning and evening, not letting fellow students know he was Li He's son." },
  { zh: "春，正月，丙子，京師地震。", literal: "In spring, the first month, on bingzi, the capital had an earthquake.", idiomatic: "In spring, in the first month, on bingzi day, the capital had an earthquake." },
  { zh: "夏，六月，旱。", literal: "In summer, the sixth month, there was drought.", idiomatic: "In summer, in the sixth month, there was drought." },
  { zh: "秋，七月，丁酉，茂陵園寢災。", literal: "In autumn, the seventh month, on dingyou, the park lodge at Maoling Mausoleum burned.", idiomatic: "In autumn, in the seventh month, on dingyou day, the park lodge at Maoling Mausoleum burned." },
  { zh: "九月，鮮卑寇漁陽。", literal: "In the ninth month the Xianbei raided Yuyang.", idiomatic: "In the ninth month the Xianbei raided Yuyang." },
  { zh: "冬，十二月，己亥，太傅桓焉免。", literal: "In winter, the twelfth month, on jihai, Grand Tutor Huan Yan was dismissed.", idiomatic: "In winter, in the twelfth month, on jihai day, Grand Tutor Huan Yan was dismissed." },
  { zh: "車騎將軍來歷罷。", literal: "General of Chariots and Cavalry Lai Li was dismissed.", idiomatic: "General of Chariots and Cavalry Lai Li was dismissed." },
  { zh: "南單于拔死，弟休利立，為去特若屍逐就單于。", literal: "The Southern Chanyu Ba died; his younger brother Xiuli was established as Chanyu Qute Ruoshizhu Jiu.", idiomatic: "The Southern Chanyu Ba died. His younger brother Xiuli was established as Chanyu Qute Ruoshizhu Jiu." },
  { zh: "帝悉召孫程等還京師。", literal: "The emperor summoned Sun Cheng and the others all back to the capital.", idiomatic: "The emperor summoned Sun Cheng and the others all back to the capital." },
  { zh: "春，正月，丙寅，赦天下。", literal: "In spring, the first month, on bingyin, all under heaven was pardoned.", idiomatic: "In spring, in the first month, on bingyin day, all under heaven was pardoned." },
  { zh: "丙子，帝加元服。", literal: "On bingzi the emperor performed the capping ceremony.", idiomatic: "On bingzi day the emperor performed the capping ceremony." },
  { zh: "夏，五月，壬辰，詔曰：「海內頗有災異，朝廷修政，太官減膳，珍玩不御。", literal: "In summer, the fifth month, on renchen, an edict said: \"Within the seas there are rather many disasters and portents; the court is reforming government, the Grand Provisioner has reduced meals, and precious curios are not used.", idiomatic: "In summer, in the fifth month, on renchen day, an edict said, \"Within the seas there are rather many disasters and portents. The court is reforming government, the Grand Provisioner has reduced meals, and precious curios are not used." },
  { zh: "而桂陽太守文礱，不惟竭忠宣暢本朝，而遠獻大珠以求幸媚，今封以還之！", literal: "Yet Administrator of Guiyang Wen Yin not only failed to exhaust loyalty and proclaim and extend this court, but from afar presented great pearls to seek favor and flattery—now they are sealed and returned to him!\"", idiomatic: "Yet Administrator of Guiyang Wen Yin not only failed to exhaust loyalty and proclaim and extend this court, but from afar presented great pearls to seek favor and flattery—now they are sealed and returned to him!\"" },
  { zh: "五州雨水。", literal: "Five provinces had rain and flood.", idiomatic: "Five provinces had rain and flooding." },
  { zh: "秋，八月，丁巳，太尉劉光、司空張皓免。", literal: "In autumn, the eighth month, on dingsi, Grand Commandant Liu Guang and Minister of Works Zhang Hao were dismissed.", idiomatic: "In autumn, in the eighth month, on dingsi day, Grand Commandant Liu Guang and Minister of Works Zhang Hao were dismissed." },
  { zh: "尚書偵射虞詡上言：「安定、北地、上郡，山川險厄，沃野千里，土宜畜牧，水可溉漕。", literal: "Investigator of the Masters of Writing Yu Xu submitted a memorial, saying: \"Anding, Beidi, and Shang commanderies have mountains and rivers perilous and narrow, fertile fields for a thousand li, soil fit for pasture, and water for irrigation and transport.", idiomatic: "Investigator of the Masters of Writing Yu Xu submitted a memorial, saying, \"Anding, Beidi, and Shang commanderies have mountains and rivers perilous and narrow, fertile fields for a thousand li, soil fit for pasture, and water for irrigation and transport." },
  { zh: "頃遭元元之災，眾羌內潰，郡縣兵荒，二十餘年。", literal: "Recently they suffered the common people's calamity; the many Qiang collapsed inward; commanderies and counties were desolate from war for more than twenty years.", idiomatic: "Recently they suffered the common people's calamity. The many Qiang collapsed inward, and commanderies and counties were desolate from war for more than twenty years." },
  { zh: "夫棄沃壤之饒，捐自然之財，不可謂利；", literal: "To abandon the richness of fertile soil and cast away nature's wealth cannot be called profit;", idiomatic: "To abandon the richness of fertile soil and cast away nature's wealth cannot be called profit;" },
  { zh: "離河山之阻，守無險之處，難以為固。", literal: "to leave the barriers of rivers and mountains and guard places without peril is hard to make secure.", idiomatic: "to leave the barriers of rivers and mountains and guard places without peril is hard to make secure." },
  { zh: "今三郡未復，園陵單外，而公卿選懦，容頭過身，張解設難，但計所費，不圖其安。", literal: "Now the three commanderies are not restored, the park mausoleums stand exposed alone, yet the dukes and ministers choose the timid, let the head pass and the body follow, spread excuses and set difficulties, reckoning only expense and not planning for security.", idiomatic: "Now the three commanderies are not restored and the park mausoleums stand exposed alone, yet the dukes and ministers choose the timid, let the head pass and the body follow, spread excuses and set difficulties, reckoning only expense and not planning for security." },
  { zh: "宜開聖聽，考行所長。", literal: "Your sage hearing should be opened and what each excels at examined.\"", idiomatic: "Your sage hearing should be opened and what each excels at examined.\"" },
  { zh: "」九月，詔復安定、北地、上郡歸舊土。", literal: "\" In the ninth month an edict restored Anding, Beidi, and Shang commanderies to their former lands.", idiomatic: "\" In the ninth month an edict restored Anding, Beidi, and Shang commanderies to their former lands." },
  { zh: "癸酉，以大鴻臚龐參為太尉、錄尚書事。", literal: "On guiyou, Grand Herald Pang Can was made Grand Commandant and Recorder of Matters Relating to the Masters of Writing.", idiomatic: "On guiyou day, Grand Herald Pang Can was made Grand Commandant and Recorder of Matters Relating to the Masters of Writing." },
  { zh: "太常王龔為司空。", literal: "Grand Master of Ceremonies Wang Gong was made Minister of Works.", idiomatic: "Grand Master of Ceremonies Wang Gong was made Minister of Works." },
  { zh: "冬，十一月，庚辰，司徒許敬免。", literal: "In winter, the eleventh month, on gengchen, Minister over the Masses Xu Jing was dismissed.", idiomatic: "In winter, in the eleventh month, on gengchen day, Minister over the Masses Xu Jing was dismissed." },
  { zh: "鮮卑寇朔方。", literal: "The Xianbei raided Shuofang.", idiomatic: "The Xianbei raided Shuofang." },
  { zh: "十二月，巳卯，以宗正弘農劉崎為司徒。", literal: "In the twelfth month, on sijimao day, made Director of the Imperial Clan Liu Qi of Hongnong Minister over the Masses.", idiomatic: "In the twelfth month, on sijimao day, Director of the Imperial Clan Liu Qi of Hongnong was made Minister over the Masses." },
  { zh: "是歲，於窴王放前殺拘彌王興，自立其子為拘彌王，而遣使者貢獻，敦煌太守徐由上求討之。", literal: "That year King Fangqian of Yutian killed King Xing of Jimi, installed his own son as king of Jimi, and sent envoys with tribute. Administrator of Dunhuang Xu You memorialized above requesting punishment.", idiomatic: "That year King Fangqian of Yutian killed King Xing of Jimi, installed his own son as king of Jimi, and sent envoys with tribute. Administrator of Dunhuang Xu You memorialized requesting that he be punished." },
  { zh: "帝赦於窴罪，令歸拘彌國；", literal: "The emperor pardoned Yutian's crime and ordered return of the Jimi state;", idiomatic: "The emperor pardoned Yutian's crime and ordered the return of the Jimi state;" },
  { zh: "放前不肯。", literal: "Fangqian refused.", idiomatic: "Fangqian refused." },
  { zh: "夏，四月，京師旱。", literal: "In summer, the fourth month, the capital suffered drought.", idiomatic: "In summer, in the fourth month, the capital suffered drought." },
  { zh: "京師及郡國十二蝗。", literal: "The capital and twelve commanderies and states suffered locusts.", idiomatic: "The capital and twelve commanderies and states suffered locusts." },
  { zh: "定遠侯班超之孫始尚帝姑陰城公主。", literal: "Marquis Dingyuan Ban Shi's grandson Shi married the emperor's paternal aunt, the Princess of Yincheng.", idiomatic: "Marquis Dingyuan Ban Shi's grandson Shi married the emperor's paternal aunt, the Princess of Yincheng." },
  { zh: "主驕淫無道；", literal: "The princess was arrogant, dissolute, and lawless;", idiomatic: "The princess was arrogant, dissolute, and lawless;" },
  { zh: "始積忿怒，伏刃殺主。", literal: "Shi accumulated resentment and anger, lay in wait with a blade, and killed the princess.", idiomatic: "Shi accumulated resentment and anger, lay in wait with a blade, and killed the princess." },
  { zh: "冬，十月，乙亥，始坐腰斬，同產皆棄市。", literal: "In winter, the tenth month, on yihai day, Shi was sentenced to execution at the waist; all siblings born of the same mother were exposed in the market.", idiomatic: "In winter, in the tenth month, on yihai day, Shi was sentenced to execution at the waist, and all siblings born of the same mother were exposed in the market." },
  { zh: "春，二月，庚午，河間孝王開薨；", literal: "In spring, the second month, on gengwu day, Filial King Kai of Hejian died;", idiomatic: "In spring, in the second month, on gengwu day, Filial King Kai of Hejian died;" },
  { zh: "子政嗣。", literal: "His son Zheng succeeded.", idiomatic: "His son Zheng succeeded." },
  { zh: "政傲很不奉法，帝以侍御史吳郡沈景有強能，擢為河間相。", literal: "Zheng was arrogant and defiant and did not follow the law. The emperor, because Attending Clerk Shen Jing of Wu commandery had strong ability, promoted him to Chancellor of Hejian.", idiomatic: "Zheng was arrogant and defiant and did not follow the law. The emperor, because Attending Clerk Shen Jing of Wu commandery had strong ability, promoted him to Chancellor of Hejian." },
  { zh: "景到國，謁王，王不正服，箕踞殿上；", literal: "Jing reached the state, called on the king; the king was not properly dressed and sat sprawled on the hall dais;", idiomatic: "When Jing reached the state and called on the king, the king was not properly dressed and sat sprawled on the hall dais;" },
  { zh: "侍郎贊拜，景峙不為禮，問王所在。", literal: "a Gentleman Attendant prompted the bow of courtesy; Jing stood erect and made no courtesy, asking where the king was.", idiomatic: "a Gentleman Attendant prompted the bow of courtesy. Jing stood erect and made no courtesy, asking where the king was." },
  { zh: "虎賁曰：「是非王邪！", literal: "A Tiger Brave said: \"Is this not the king!", idiomatic: "A Tiger Brave said, \"Is this not the king!" },
  { zh: "」景曰：「王不正服，常人何別！", literal: "\" Jing said: \"The king is not properly dressed—how is he different from an ordinary man!", idiomatic: "\" Jing said, \"The king is not properly dressed—how is he different from an ordinary man!" },
  { zh: "今相謁王，豈謁無禮者邪！", literal: "\" Now the chancellor calls on the king—does he call on one without courtesy!", idiomatic: "\" Now the chancellor calls on the king—does he call on one without courtesy!" },
  { zh: "」王慚而更服，景然後拜；", literal: "\" The king was ashamed and changed into proper dress; Jing then bowed;", idiomatic: "\" The king was ashamed and changed into proper dress; Jing then bowed;" },
  { zh: "出，住宮門外，請王傅責之曰：「前發京師，陛見受詔，以王不恭，使相檢督。", literal: "going out, he stopped outside the palace gate and summoned the king's tutor to reprove him, saying: \"Before leaving the capital I had audience and received an edict, because the king was disrespectful, to have the chancellor inspect and supervise.", idiomatic: "Going out, he stopped outside the palace gate and summoned the king's tutor to reprove him, saying, \"Before leaving the capital I had audience and received an edict, because the king was disrespectful, to have the chancellor inspect and supervise." },
  { zh: "諸君空受爵祿，曾無訓導之義！", literal: "\" You gentlemen vainly receive rank and salary yet utterly lack the duty of instruction and guidance!", idiomatic: "\" You gentlemen vainly receive rank and salary yet utterly lack the duty of instruction and guidance!" },
  { zh: "」因奏治其罪，詔書讓政而詰責傅。", literal: "\" Thereupon he memorialized to punish their offenses; an imperial edict reproved Zheng and sharply rebuked the tutor.", idiomatic: "\" Thereupon he memorialized to punish their offenses. An imperial edict reproved Zheng and sharply rebuked the tutor." },
  { zh: "景因捕諸奸人，奏案其罪，殺戮尤惡者數十人，出冤獄百餘人。", literal: "Jing then arrested various wicked men, memorialized cases of their crimes, executed several tens of the most vicious, and released more than a hundred from unjust imprisonment.", idiomatic: "Jing then arrested various wicked men, memorialized cases of their crimes, executed several tens of the most vicious, and released more than a hundred from unjust imprisonment." },
  { zh: "政遂為改節，悔過自修。", literal: "Zheng thereupon changed his conduct, repented of faults, and cultivated himself.", idiomatic: "Zheng thereupon changed his conduct, repented of his faults, and cultivated himself." },
  { zh: "帝以伊吾膏腴之地，傍近西域，匈奴資之以為鈔暴；", literal: "The emperor, because Yiwu was fertile land lying close to the Western Regions, and the Xiongnu relied on it for raiding and plunder;", idiomatic: "The emperor, because Yiwu was fertile land lying close to the Western Regions and the Xiongnu relied on it for raiding and plunder," },
  { zh: "三月，辛亥，復令開設屯田，如永元時事，置伊吾司馬一人。", literal: "in the third month, on xinhai day, again ordered the opening of military colonies as in the Yongyuan period, and stationed one Major of Yiwu.", idiomatic: "in the third month, on xinhai day, again ordered the opening of military colonies as in the Yongyuan period and stationed one Major of Yiwu." },
  { zh: "初，安帝薄於藝文，博士不復講習，朋徒相視怠散，學舍頹敝，鞠為園蔬，或牧兒、蕘豎薪刈其下。", literal: "Earlier Emperor An was slight toward literary arts; Erudites no longer lectured and studied, students looked at one another in idleness and dispersion, school buildings fell into ruin, turned into vegetable gardens, and herd boys and firewood gatherers cut fuel beneath them.", idiomatic: "Earlier Emperor An was slight toward literary arts. Erudites no longer lectured and studied, students looked at one another in idleness and dispersion, school buildings fell into ruin and turned into vegetable gardens, and herd boys and firewood gatherers cut fuel beneath them." },
  { zh: "將作大匠翟酺上疏請更修繕，誘進後學，帝從之。", literal: "Master of Works Zhai Pu submitted a memorial requesting renewed repair and ornament, to attract and advance later students; the emperor followed it.", idiomatic: "Master of Works Zhai Pu submitted a memorial requesting renewed repair and ornament to attract and advance later students, and the emperor followed it." },
  { zh: "秋，九月，繕起太學，凡所造構二百四十房，千八百五十室。", literal: "In autumn, the ninth month, the Imperial University was repaired and raised; in all structures built numbered two hundred forty chambers and one thousand eight hundred fifty rooms.", idiomatic: "In autumn, in the ninth month, the Imperial University was repaired and raised. In all, two hundred forty chambers and one thousand eight hundred fifty rooms were built." },
  { zh: "護烏桓校尉耿曄遣兵擊鮮卑，破之。", literal: "Colonel Protector of the Wuhuan Geng Tan sent troops to attack the Xianbei and defeated them.", idiomatic: "Colonel Protector of the Wuhuan Geng Tan sent troops to attack the Xianbei and defeated them." },
  { zh: "護羌校尉韓皓轉湟中屯田置兩河間，以逼群羌。", literal: "Colonel Protector of the Qiang Han Hao moved the garrison farms of Huangzhong and established them between the Two Rivers to press the various Qiang.", idiomatic: "Colonel Protector of the Qiang Han Hao moved the garrison farms of Huangzhong and established them between the Two Rivers to press the various Qiang." },
  { zh: "皓坐事徵，以張掖太守馬續代為校尉。", literal: "Hao was summoned because of an offense; Administrator of Zhangye Ma Xu was made colonel in his place.", idiomatic: "Hao was summoned because of an offense, and Administrator of Zhangye Ma Xu was made colonel in his place." },
  { zh: "兩河間羌以屯田近之，恐必見圖，乃解仇詛盟，各自儆備；", literal: "The Qiang between the Two Rivers, because the garrison farms were near them, feared they would surely be plotted against; thereupon they dissolved enmity and oath alliances and each took precautions;", idiomatic: "The Qiang between the Two Rivers, because the garrison farms were near them, feared they would surely be plotted against. Thereupon they dissolved enmity and oath alliances and each took precautions;" },
  { zh: "續上移屯田還湟中，羌意乃安。", literal: "Xu memorialized above to move the garrison farms back to Huangzhong, and the Qiang's minds then were at ease.", idiomatic: "Xu memorialized to move the garrison farms back to Huangzhong, and the Qiang's minds then were at ease." },
  { zh: "帝欲立皇后，而貴人有寵者四人，莫知所建，議欲探籌，以神定選。", literal: "The emperor wished to establish an empress, but among honored ladies with favor there were four, and none knew whom to establish. Deliberation wished to draw lots to let the spirits fix the choice.", idiomatic: "The emperor wished to establish an empress, but among honored ladies with favor there were four, and none knew whom to establish. Deliberation wished to draw lots to let the spirits fix the choice." },
  { zh: "尚書僕射南郡胡廣與尚書馮翊郭虔、史敞上疏諫曰：「竊見詔書，以立後事大，謙大自專，欲假之籌策，決疑靈神；", literal: "Vice Director of the Secretariat Hu Guang of Nan commandery together with Directors Guo Qian of Fengyi and Shi Chang submitted a memorial remonstrating, saying: \"Your servant has seen the edict, that establishing the empress is a great affair, and in great humility one would not decide alone, wishing to borrow lots and stratagems and let numinous spirits resolve doubt;", idiomatic: "Vice Director of the Secretariat Hu Guang of Nan commandery together with Directors Guo Qian of Fengyi and Shi Chang submitted a memorial remonstrating, saying, \"Your servant has seen the edict, that establishing the empress is a great affair, and in great humility one would not decide alone, wishing to borrow lots and stratagems and let numinous spirits resolve doubt;" },
  { zh: "篇籍所記，祖宗典故，未嘗有也。", literal: "\" What the classics and records note, the ancestral precedents, have never had this.", idiomatic: "\" What the classics and records note, the ancestral precedents, have never had this." },
  { zh: "恃神任筮，既不必當賢；", literal: "\" Relying on spirits and trusting divination, one will not necessarily obtain the worthy;", idiomatic: "\" Relying on spirits and trusting divination, one will not necessarily obtain the worthy;" },
  { zh: "就值其人，猶非德選。", literal: "\" even if one happens on the right person, it is still not selection by virtue.", idiomatic: "\" even if one happens on the right person, it is still not selection by virtue." },
  { zh: "夫歧嶷形於自然，俔天必有異表，宜參良家，簡求有德，德同以年，年鈞以貌；", literal: "\" Precocious intelligence takes form from nature; resemblance to heaven surely has an unusual appearance. It is fitting to consult good families, select and seek the virtuous—where virtue is equal, use age; where age is equal, use appearance;", idiomatic: "\" Precocious intelligence takes form from nature; resemblance to heaven surely has an unusual appearance. It is fitting to consult good families, select and seek the virtuous—where virtue is equal, use age; where age is equal, use appearance;" },
  { zh: "稽之典經，斷之聖慮。", literal: "\" examine against the canonical classics and decide by the sage's deliberation.", idiomatic: "\" examine against the canonical classics and decide by the sage's deliberation." },
  { zh: "」帝從之。", literal: "\" The emperor followed it.", idiomatic: "\" The emperor followed it." },
  { zh: "恭懷皇后弟子乘氏侯商之女，選入掖庭為貴人，常特被引御，從容辭曰：「夫陽以博施為德，陰以不專為義。", literal: "The niece of Empress Gonghuai, daughter of Marquis Shang of Chengyi, was selected into the Palace Rear Apartments as an Honored Lady and was often specially summoned for the emperor's company. She calmly declined, saying: \"Yang takes broad bestowal as virtue; yin takes not being exclusive as righteousness.", idiomatic: "The niece of Empress Gonghuai, daughter of Marquis Shang of Chengyi, was selected into the Palace Rear Apartments as an Honored Lady and was often specially summoned for the emperor's company. She calmly declined, saying, \"Yang takes broad bestowal as virtue; yin takes not being exclusive as righteousness." },
  { zh: "《螽斯》則百福所由興也。", literal: "\" The \"Zhongsi\" is where the hundred blessings arise.", idiomatic: "\" The \"Zhongsi\" is where the hundred blessings arise." },
  { zh: "願陛下思雲雨之均澤，小妾得免於罪。", literal: "\" Your servant wishes Your Majesty to think of the even moisture of cloud and rain, that your humble servant may escape offense.", idiomatic: "\" Your servant wishes Your Majesty to think of the even moisture of cloud and rain, that your humble servant may escape offense." },
  { zh: "」帝由是賢之。", literal: "\" The emperor thereby regarded her as worthy.", idiomatic: "\" The emperor thereby regarded her as worthy." },
  { zh: "春，正月，乙巳，立貴人梁氏為皇后。", literal: "In spring, the first month, on yisi day, established Honored Lady Liang as empress.", idiomatic: "In spring, in the first month, on yisi day, Honored Lady Liang was established as empress." },
  { zh: "京師旱。", literal: "The capital suffered drought.", idiomatic: "The capital suffered drought." },
  { zh: "三月，揚州六郡妖賊章河等寇四十九縣，殺傷長吏。", literal: "In the third month, demon bandits Zhang He and others of six Yangzhou commanderies raided forty-nine counties and killed and wounded chief officials.", idiomatic: "In the third month, demon bandits Zhang He and others of six Yangzhou commanderies raided forty-nine counties and killed and wounded chief officials." },
  { zh: "庚寅，赦天下，改元。", literal: "On gengyin day, amnestied the realm and changed the reign title.", idiomatic: "On gengyin day, the realm was amnestied and the reign title was changed." },
  { zh: "夏，四月，梁商加位特進；", literal: "In summer, the fourth month, Liang Shang was given the additional rank of Special Advance;", idiomatic: "In summer, in the fourth month, Liang Shang was given the additional rank of Special Advance;" },
  { zh: "頃之，拜執金吾。", literal: "before long he was appointed Commandant of Justice.", idiomatic: "before long he was appointed Commandant of Justice." },
  { zh: "冬，耿曄遣烏桓戎末魔等鈔擊鮮卑，大獲而還。", literal: "In winter, Geng Tan sent the Wuhuan Rongmomo and others to raid the Xianbei, gained greatly, and returned.", idiomatic: "In winter, Geng Tan sent the Wuhuan Rongmomo and others to raid the Xianbei, gained greatly, and returned." },
  { zh: "鮮卑復寇遼東屬國，耿曄移屯遼東無慮城以拒之。", literal: "The Xianbei again raided the Dependent State of Liaodong; Geng Tan moved his encampment to Wulü city in Liaodong to resist them.", idiomatic: "The Xianbei again raided the Dependent State of Liaodong. Geng Tan moved his encampment to Wulü city in Liaodong to resist them." },
  { zh: "尚書令左雄上疏曰：「昔宣帝以為吏數變易，則下不安業；", literal: "Director of the Secretariat Zuo Xiong submitted a memorial, saying: \"Formerly Emperor Xuan held that if officials were repeatedly changed, then inferiors would not settle in their occupations;", idiomatic: "Director of the Secretariat Zuo Xiong submitted a memorial, saying, \"Formerly Emperor Xuan held that if officials were repeatedly changed, then inferiors would not settle in their occupations;" },
  { zh: "久於其事，則民服教化。", literal: "\" long in their affairs, then the people submit to transformation and instruction.", idiomatic: "\" long in their affairs, then the people submit to transformation and instruction." },
  { zh: "其有政治者，輒以璽書勉勵，增秩賜金，公卿缺則以次用之。", literal: "\" Those who had good government were at once encouraged by imperial rescript with seal, given increased rank and bestowed gold; when public ministers and excellencies were vacant, they were used in order.", idiomatic: "\" Those who had good government were at once encouraged by imperial rescript with seal, given increased rank and bestowed gold. When public ministers and excellencies were vacant, they were used in order." },
  { zh: "是以吏稱其職，民安其業，漢世良吏，於茲為盛。", literal: "\" Thus officials matched their duties and the people were secure in their occupations; good officials of the Han age reached their greatest abundance then.", idiomatic: "\" Thus officials matched their duties and the people were secure in their occupations. Good officials of the Han age reached their greatest abundance then." },
  { zh: "今典城百里，轉動無常，各懷一切，莫慮長久。", literal: "\" Today those governing cities of a hundred li shift without constancy; each harbors a one-time expedient and none considers the long term.", idiomatic: "\" Today those governing cities of a hundred li shift without constancy. Each harbors a one-time expedient and none considers the long term." },
  { zh: "謂殺害不辜為威風，聚斂整辦為賢能；", literal: "\" They call killing the innocent \"prestigious wind,\" and gathering and levying with tight preparation \"worth and ability;\"", idiomatic: "\" They call killing the innocent \"prestigious wind,\" and gathering and levying with tight preparation \"worth and ability;\"" },
  { zh: "以治己安民為劣弱，奉法循理為不治。", literal: "\" they take governing oneself and securing the people as inferior weakness, and following law and adhering to principle as non-government.", idiomatic: "\" they take governing oneself and securing the people as inferior weakness, and following law and adhering to principle as non-government." },
  { zh: "髡鉗之戮，生於睚眥；", literal: "\" punishments of shaving and shackling arise from the glance of an eye;", idiomatic: "\" punishments of shaving and shackling arise from the glance of an eye;" },
  { zh: "覆屍之禍，成於喜怒。", literal: "\" disasters of corpses heaped over one another are completed from joy and anger.", idiomatic: "\" disasters of corpses heaped over one another are completed from joy and anger." },
  { zh: "視民如寇仇，稅之如豺虎。", literal: "\" They regard the people as bandit enemies and tax them like jackals and tigers.", idiomatic: "\" They regard the people as bandit enemies and tax them like jackals and tigers." },
  { zh: "監司項背相望，與同疾疢，見非不舉，聞惡不察。", literal: "\" Supervisors and inspectors stand back to back in sight, sharing the same disease—seeing wrong and not reporting it, hearing evil and not investigating.", idiomatic: "\" Supervisors and inspectors stand back to back in sight, sharing the same disease—seeing wrong and not reporting it, hearing evil and not investigating." },
  { zh: "觀政於亭傳，責成於期月；", literal: "\" They observe government at post stations and demand achievement within a month;", idiomatic: "\" They observe government at post stations and demand achievement within a month;" },
  { zh: "言善不稱德，論功不據實。", literal: "\" speaking of goodness without weighing virtue, discussing merit without basing on fact.", idiomatic: "\" speaking of goodness without weighing virtue, discussing merit without basing on fact." },
  { zh: "虛誕者獲譽，拘檢者離毀；", literal: "\" the empty and false gain praise; the restrained and careful meet slander;", idiomatic: "\" the empty and false gain praise; the restrained and careful meet slander;" },
  { zh: "或因罪而引高，或色斯而求名，州宰不覆，競共辟召，踴躍升騰，超等逾匹。", literal: "\" some, because of crime, draw themselves high; some, seeing the color, seek fame. Prefects do not review them; they compete in summoning and appointing, leaping and soaring upward, surpassing rank and exceeding peers.", idiomatic: "\" some, because of crime, draw themselves high; some, seeing the color, seek fame. Prefects do not review them. They compete in summoning and appointing, leaping and soaring upward, surpassing rank and exceeding peers." },
  { zh: "或考奏捕案，而亡不受罪，會赦行賂，復見洗滌，朱紫同色，清濁不分。", literal: "\" Some are examined and memorialized for arrest and trial yet flee and do not receive punishment; when an amnesty comes they go with bribes and are again washed clean—vermilion and purple the same color, clear and turbid undivided.", idiomatic: "\" Some are examined and memorialized for arrest and trial yet flee and do not receive punishment. When an amnesty comes they go with bribes and are again washed clean—vermilion and purple the same color, clear and turbid undivided." },
  { zh: "故使奸猾枉濫，輕忽去就，拜除如流，缺動百數。", literal: "\" Therefore the crafty and slippery run wild, lightly heed coming and going, appointments and dismissals flow like water, and vacancies stir by the hundreds.", idiomatic: "\" Therefore the crafty and slippery run wild, lightly heed coming and going, appointments and dismissals flow like water, and vacancies stir by the hundreds." },
  { zh: "鄉官、部吏，職賤祿薄，車馬衣服，一出於民，廉者取足，貪者充家；", literal: "\" Village officers and department clerks have mean duties and thin salaries, yet carriage, horse, and clothing all come from the people—the honest take enough, the greedy fill their houses;", idiomatic: "\" Village officers and department clerks have mean duties and thin salaries, yet carriage, horse, and clothing all come from the people—the honest take enough, the greedy fill their houses;" },
  { zh: "特選、橫調，紛紛不絕，送迎煩費，損政傷民。", literal: "\" special selections and forced levies follow one another without cease; the trouble and expense of seeing off and welcoming harm government and injure the people.", idiomatic: "\" special selections and forced levies follow one another without cease. The trouble and expense of seeing off and welcoming harm government and injure the people." },
  { zh: "和氣未洽，災眚不消，咎皆在此。", literal: "\" Harmonious qi is not attained, disasters and omens are not dispelled—the blame all lies here.", idiomatic: "\" Harmonious qi is not attained, disasters and omens are not dispelled—the blame all lies here." },
  { zh: "臣愚以為守相、長吏惠和有顯效者，可就增秩，勿移徙；", literal: "\" Your servant foolishly thinks that where prefects, chancellors, and chief officials have kindness and harmony with clear effect, one may increase their rank in place and not transfer them;", idiomatic: "\" Your servant foolishly thinks that where prefects, chancellors, and chief officials have kindness and harmony with clear effect, one may increase their rank in place and not transfer them;" },
  { zh: "非父母喪，不得去官。", literal: "\" except for parents' mourning they may not leave office.", idiomatic: "\" except for parents' mourning they may not leave office." },
  { zh: "其不從法禁，不式王命，錮之終身，雖會赦令，不得齒列。", literal: "\" Those who do not follow legal prohibitions and do not model the king's command should be barred for life; though they meet an amnesty edict, they may not be ranked in the roster.", idiomatic: "\" Those who do not follow legal prohibitions and do not model the king's command should be barred for life. Though they meet an amnesty edict, they may not be ranked in the roster." },
  { zh: "若被劾奏，亡不就法者，徙家邊郡，以懲其後。", literal: "\" If impeached and memorialized yet they flee and do not submit to law, move their families to frontier commanderies to warn those who come after.", idiomatic: "\" If impeached and memorialized yet they flee and do not submit to law, move their families to frontier commanderies to warn those who come after." },
  { zh: "其鄉部親民之吏，皆用儒生清白任從政者，寬其負算，增其秩祿；", literal: "\" As for officers of villages and departments who are close to the people, all should employ Confucian scholars who are pure and clear and fit for government, relax their tax assessments, and increase their rank and salary;", idiomatic: "\" As for officers of villages and departments who are close to the people, all should employ Confucian scholars who are pure and clear and fit for government, relax their tax assessments, and increase their rank and salary;" },
  { zh: "吏職滿歲，宰府州郡乃得辟舉。", literal: "\" only when an officer's duty is full for a year may the prefect's office, the commandery, or the province summon and recommend.", idiomatic: "\" only when an officer's duty is full for a year may the prefect's office, the commandery, or the province summon and recommend." },
  { zh: "如此，威福之路塞，虛偽之端絕，送迎之役損，賦斂之源息，循理之吏得成其化，率土之民各寧其所矣。", literal: "\" If so, the road of authority and favor is blocked, the source of emptiness and falsehood is cut off, the labor of seeing off and welcoming is reduced, the spring of levies and collections is stilled, officers who follow principle can complete their transformation, and the people of the whole realm each secure their place.", idiomatic: "\" If so, the road of authority and favor is blocked, the source of emptiness and falsehood is cut off, the labor of seeing off and welcoming is reduced, the spring of levies and collections is stilled, officers who follow principle can complete their transformation, and the people of the whole realm each secure their place." },
  { zh: "」帝感其言，復申無故去官之禁，又下有司考吏治真偽，詳所施行；", literal: "\" The emperor was moved by his words, again proclaimed the prohibition on leaving office without cause, and also ordered the relevant offices to examine officials' government for truth and falsehood, detailing what was implemented;", idiomatic: "\" The emperor was moved by his words, again proclaimed the prohibition on leaving office without cause, and also ordered the relevant offices to examine officials' government for truth and falsehood, detailing what was implemented;" },
  { zh: "而宦官不便，終不能行。", literal: "\" but the eunuchs found it inconvenient, and in the end it could not be carried out.", idiomatic: "\" but the eunuchs found it inconvenient, and in the end it could not be carried out." },
  { zh: "雄又上言：「孔子曰：『四十不惑』，《禮》稱強仕。", literal: "Xiong again submitted words: \"Confucius said: 'At forty one is free of doubt'; the Rites call it strong service.", idiomatic: "Xiong again submitted words, \"Confucius said, 'At forty one is free of doubt'; the Rites call it strong service." },
  { zh: "請自今，孝廉年不滿四十，不得察舉，皆先詣公府，諸生試家法，文吏課箋奏，副之端門，練其虛實，以觀異能，以美風俗。", literal: "\" Your servant requests that from today Filial and Incorrupt candidates under forty years of age may not be examined and recommended; all should first go to the public offices—students tested on family learning, clerical officials examined on memorials and reports—copies posted at the Duan Gate to sift emptiness and substance, observe unusual ability, and beautify custom.", idiomatic: "\" Your servant requests that from today Filial and Incorrupt candidates under forty years of age may not be examined and recommended. All should first go to the public offices—students tested on family learning, clerical officials examined on memorials and reports—copies posted at the Duan Gate to sift emptiness and substance, observe unusual ability, and beautify custom." },
  { zh: "有不承科令者，正其罪法。", literal: "\" Those who do not accept the regulations and orders—correct them by penal law.", idiomatic: "\" Those who do not accept the regulations and orders—correct them by penal law." },
  { zh: "若有茂材異行，自可不拘年齒。", literal: "\" If there are flourishing talent and unusual conduct, naturally age need not be restricted.", idiomatic: "\" If there are flourishing talent and unusual conduct, naturally age need not be restricted." },
  { zh: "」帝從之。", literal: "\" The emperor followed it.", idiomatic: "\" The emperor followed it." },
  { zh: "胡廣、郭虔、史敞上書駁之曰：「凡選舉因才，無拘定制。", literal: "Hu Guang, Guo Qian, and Shi Chang submitted a memorial refuting it, saying: \"In general selection and recommendation follow talent, without restriction to fixed regulations.", idiomatic: "Hu Guang, Guo Qian, and Shi Chang submitted a memorial refuting it, saying, \"In general selection and recommendation follow talent, without restriction to fixed regulations." },
  { zh: "六奇之策，不出經學；", literal: "\" The six marvelous stratagems did not come from classical learning;", idiomatic: "\" The six marvelous stratagems did not come from classical learning;" },
  { zh: "鄭、阿之政，非必章奏；", literal: "\" the government of Zheng and A was not necessarily by formal memorial;", idiomatic: "\" the government of Zheng and A was not necessarily by formal memorial;" },
  { zh: "甘、奇顯用，年乖強仁；", literal: "\" Gan and Qi were prominently employed though their years fell short of strong service;", idiomatic: "\" Gan and Qi were prominently employed though their years fell short of strong service;" },
  { zh: "終、賈揚聲，亦在弱冠。", literal: "\" Zhong and Jia raised their fame also in the weak-capping years.", idiomatic: "\" Zhong and Jia raised their fame also in the weak-capping years." },
  { zh: "前世以來，貢舉之制，莫或回革。", literal: "\" From former ages until now, the system of tribute recommendation has had none who turned and reformed it.", idiomatic: "\" From former ages until now, the system of tribute recommendation has had none who turned and reformed it." },
  { zh: "今以一臣之言，剷戾舊章，便利未明，眾心不厭。", literal: "\" Now on one minister's words to cut and violate old statutes, the benefit is not clear and the hearts of the multitude are not satisfied.", idiomatic: "\" Now on one minister's words to cut and violate old statutes, the benefit is not clear and the hearts of the multitude are not satisfied." },
  { zh: "矯枉變常，政之所重，而不訪台司，不謀卿士，若事下之後，議者剝異，異之則朝失其便，同之則王言已行。", literal: "\" To straighten the bent and change the constant is what government weighs heavily, yet without consulting the terrace offices or deliberating with ministers and nobles—if after the matter is sent down deliberators peel away in difference, to differ is for the court to lose its convenience, to agree is for the king's words already to have gone forth.", idiomatic: "\" To straighten the bent and change the constant is what government weighs heavily, yet without consulting the terrace offices or deliberating with ministers and nobles—if after the matter is sent down deliberators peel away in difference, to differ is for the court to lose its convenience, to agree is for the king's words already to have gone forth." },
  { zh: "臣愚以為可宣下百官，參其同異，然後覽擇勝否，詳采厥衷。", literal: "\" Your servant foolishly thinks it can be proclaimed down to the hundred officials, have them compare agreement and difference, and then survey and choose the winning and losing, carefully gathering the inner meaning.", idiomatic: "\" Your servant foolishly thinks it can be proclaimed down to the hundred officials, have them compare agreement and difference, and then survey and choose the winning and losing, carefully gathering the inner meaning." },
  { zh: "」帝不從。", literal: "\" The emperor did not follow it.", idiomatic: "\" The emperor did not follow it." },
  { zh: "辛卯，初令「郡國舉孝廉，限年四十以上；", literal: "On xinmao day, for the first time ordered: \"Commanderies and states recommending Filial and Incorrupt are limited to forty years of age and above;", idiomatic: "On xinmao day, for the first time it was ordered: \"Commanderies and states recommending Filial and Incorrupt are limited to forty years of age and above;" },
  { zh: "諸生通章句，文吏能箋奏，乃得應選。", literal: "Students had to master chapter-and-verse commentary, clerical officials had to be able to draft memorials—only then could they qualify for selection.", idiomatic: "Students had to master chapter-and-verse commentary and clerical officials had to be able to draft memorials—only then could they qualify for selection." },
  { zh: "其有茂才異行，若顏淵、子奇，不拘年齒。", literal: "Those with outstanding talent and exceptional conduct, such as Yan Yuan and Ziqi, were not bound by age.", idiomatic: "Those with outstanding talent and exceptional conduct, such as Yan Yuan and Ziqi, were not bound by age limits." },
  { zh: "」久之，廣陵所舉孝廉徐淑，年未四十。", literal: "After some time, Xu Shu, a filial and incorrupt candidate recommended by Guangling, was not yet forty.", idiomatic: "After some time, Xu Shu, a filial and incorrupt candidate recommended by Guangling, was not yet forty." },
  { zh: "台郎詰之，對曰：「詔書曰：『有如顏回、子奇，不拘年齒。", literal: "A bureau gentleman interrogated him; he replied: \"The edict says: 'For those like Yan Hui and Ziqi, do not bind by age.'\"", idiomatic: "A bureau gentleman interrogated him. He replied, \"The edict says, 'For those like Yan Hui and Ziqi, do not bind by age.'\"" },
  { zh: "』是故本郡以臣充選。", literal: "\"Therefore my native commandery recommended your servant to fill the selection.\"", idiomatic: "\"Therefore my native commandery recommended me to fill the selection.\"" },
  { zh: "」郎不能屈。", literal: "The gentleman could not refute him.", idiomatic: "The gentleman could not refute him." },
  { zh: "左雄詰之曰：「昔顏回聞一知十，孝廉聞一知幾邪？", literal: "Zuo Xiong interrogated him, saying: \"Formerly Yan Hui heard one thing and knew ten—how many does the filial candidate hear one and know?\"", idiomatic: "Zuo Xiong interrogated him, saying, \"Formerly Yan Hui heard one thing and knew ten—how many things does the filial candidate hear one and know?\"" },
  { zh: "」淑無以對，乃罷卻之。", literal: "Shu had no reply and was dismissed.", idiomatic: "Shu had no reply and was dismissed." },
  { zh: "郡守坐免。", literal: "The commandery administrator was dismissed from office.", idiomatic: "The commandery administrator was dismissed from office." },
  { zh: "袁宏論曰：夫謀事作制，以經世訓物，必使可為也。", literal: "Yuan Hong commented: To plan affairs and establish institutions, to govern the age and instruct things, one must make them practicable.", idiomatic: "Yuan Hong commented: To plan affairs and establish institutions, to govern the age and instruct things, one must make them practicable." },
  { zh: "古者四十而仕，非謂彈冠之會必將是年也。", literal: "In antiquity one took office at forty—this did not mean the moment of putting on one's cap must be exactly that year.", idiomatic: "In antiquity one took office at forty—this did not mean one had to put on one's cap in exactly that year." },
  { zh: "以為可事之時在於強盛，故舉其大限以為民衷。", literal: "It was held that the time when one could serve affairs was in one's prime strength, so they took this great limit as the people's standard.", idiomatic: "It was held that the time when one could handle affairs was in one's prime strength, so they took this upper limit as the people's standard." },
  { zh: "且顏淵、子奇，曠代一有，而欲以斯為格，豈不偏乎！", literal: "Moreover Yan Yuan and Ziqi appear perhaps once in an age—yet to take them as the measure, would that not be skewed!", idiomatic: "Moreover Yan Yuan and Ziqi appear perhaps once in an age—yet to take them as the standard, would that not be skewed!" },
  { zh: "然雄公直精明，能審核真偽，決志行之。", literal: "Yet Xiong was upright and keen, able to examine truth from falsehood, and resolved to carry it out.", idiomatic: "Yet Xiong was upright and keen, able to distinguish truth from falsehood, and resolved to carry it out." },
  { zh: "頃之，胡廣出為濟陰太守，與諸郡守十餘人皆坐謬舉免黜；", literal: "Before long, Hu Guang went out as Administrator of Jiyin, and more than ten commandery administrators including him were all dismissed for mistaken recommendations;", idiomatic: "Before long, Hu Guang went out as Administrator of Jiyin, and more than ten commandery administrators including him were all dismissed for mistaken recommendations;" },
  { zh: "唯汝南陳蕃、穎川李膺、下邳陳球等三十餘人得拜郎中。", literal: "only Chen Fan of Runan, Li Ying of Yingchuan, Chen Qiu of Xiapi, and more than thirty others were appointed as Palace Gentlemen.", idiomatic: "only Chen Fan of Runan, Li Ying of Yingchuan, Chen Qiu of Xiapi, and more than thirty others were appointed as Palace Gentlemen." },
  { zh: "自是牧、守畏栗，莫敢輕舉。", literal: "From this the governors and administrators were fearful and did not dare recommend lightly.", idiomatic: "From this the governors and administrators were fearful and did not dare recommend lightly." },
  { zh: "迄於永嘉，察選清平，多得其人。", literal: "Down to the Yongjia era, examinations and selections were clear and even, and mostly obtained the right men.", idiomatic: "Down to the Yongjia era, examinations and selections were clear and fair, and mostly obtained the right men." },
  { zh: "閏月，庚子，恭陵百丈廡災。", literal: "In the intercalary month, on gengzi day, the hundred-zhang gallery of Gong Mausoleum caught fire.", idiomatic: "In the intercalary month, on gengzi day, the hundred-zhang gallery of Gong Mausoleum caught fire." },
  { zh: "上聞北海郎顗精於陰陽之學。", literal: "The Emperor heard that Lang Gu, Gentleman of Beihai, was expert in yin-yang studies.", idiomatic: "The Emperor heard that Lang Gu, Gentleman of Beihai, was expert in yin-yang studies." },
  { zh: "春，正月，詔公車徵顗，問以災異。", literal: "In spring, the first month, an edict ordered the imperial carriage office to summon Gu and question him on calamities and prodigies.", idiomatic: "In spring, in the first month, an edict ordered the imperial carriage office to summon Gu and question him on calamities and prodigies." },
  { zh: "顗上章曰：「三公上應臺階，不同元首，政失其道，則寒陰反節。", literal: "Gu submitted a memorial, saying: \"The Three Excellencies correspond to the terrace steps, different from the head; when government loses the Way, cold yin reverses the seasons.\"", idiomatic: "Gu submitted a memorial, saying, \"The Three Excellencies correspond to the terrace steps, distinct from the sovereign; when government loses the Way, cold yin reverses the seasons.\"" },
  { zh: "今之在位，競托高虛，納累鐘之奉，亡天下之憂。", literal: "\"Those now in office compete in resting on high emptiness, receive stipends stacked like bells, and lack care for all under heaven.\"", idiomatic: "\"Those now in office compete in resting on lofty emptiness, receive stipends heaped like bells, and lack care for all under heaven.\"" },
  { zh: "棲遲偃仰，寢疾自逸，被策文，得賜錢，即復起矣，何疾之易而愈之速！", literal: "\"They linger reclining, feign illness and indulge ease; given an edict of appointment and granted money, they rise at once—how easily illness vanishes and recovery is swift!\"", idiomatic: "\"They linger reclining, feign illness and indulge in ease; given an edict of appointment and granted money, they rise at once—how easily illness vanishes and recovery is swift!\"" },
  { zh: "以此消伏災眚，興致昇平，其可得乎！", literal: "\"To eliminate calamities on this basis and bring rising peace—can it be obtained!\"", idiomatic: "\"To eliminate calamities on this basis and bring rising peace—how can it be obtained!\"" },
  { zh: "今選牧、守，委任三府；", literal: "\"Now in selecting governors and administrators, entrustment lies with the three offices;\"", idiomatic: "\"Now in selecting governors and administrators, entrustment lies with the three offices;\"" },
  { zh: "長吏不良，既咎州、郡，州、郡有失，豈得不歸責舉者！", literal: "\"when subordinate officials are bad, blame falls on province and commandery; when province and commandery err, how can blame not return on the recommenders!\"", idiomatic: "\"when subordinate officials are bad, blame falls on province and commandery; when province and commandery err, how can blame not return on those who recommended them!\"" },
  { zh: "而陛下崇之彌優，自下慢事愈甚，所謂『大網疏，小網數』。", literal: "\"Yet Your Majesty honors them ever more generously, while slackness below grows ever worse—this is what is called 'the great net is coarse, the small net is dense.'\"", idiomatic: "\"Yet Your Majesty honors them ever more generously, while slackness below grows ever worse—this is what is called 'the great net is coarse, the small net is dense.'\"" },
  { zh: "三公非臣之仇，臣非狂夫之作，所以發憤忘食，懇懇不已者，誠念朝廷欲致興平。", literal: "\"The Three Excellencies are not your servant's enemies; your servant is no madman's composition. The reason I forget food in indignation and plead unceasingly is truly that I think the court wishes to attain peace and thriving.\"", idiomatic: "\"The Three Excellencies are not your servant's enemies, and your servant is no madman's scribbling. The reason I forget food in indignation and plead unceasingly is truly that I believe the court wishes to attain peace and thriving.\"" },
  { zh: "臣書不擇言，死不敢恨！", literal: "\"Your servant's writing does not choose words; death I dare not resent!\"", idiomatic: "\"Your servant's writing does not choose words; I dare not resent death!\"" },
  { zh: "」因條便宜七事：「一，園陵火災，宜念百姓之勞，罷繕修之役。", literal: "Thereupon he set forth seven expedient measures: \"First, the park-mausoleum fire—consider the people's toil and halt repair labor.\"", idiomatic: "Thereupon he set forth seven expedient measures: \"First, the park-mausoleum fire—consider the people's toil and halt repair labor.\"" },
  { zh: "二，立春以後陰寒失節，宜採納良臣，以助聖化。", literal: "Second, after spring begins yin-cold loses the seasons—select and employ good ministers to aid sagely transformation.", idiomatic: "Second, after spring begins yin-cold loses the seasons—select and employ good ministers to aid sagely transformation." },
  { zh: "三，今年少陽之歲，春當旱，夏必有水，宜遵前典，惟節惟約。", literal: "Third, this year is a lesser yang year—spring should bring drought, summer will surely bring flood—follow former canons, be frugal and restrained.", idiomatic: "Third, this year is a lesser yang year—spring should bring drought and summer will surely bring flood—follow former canons and be frugal and restrained." },
  { zh: "四，去年八月，熒惑出入軒轅，宜簡出宮女，恣其姻嫁。", literal: "Fourth, last year in the eighth month Mars entered and left Xuanyuan—simplify and release palace women and let them marry as they will.", idiomatic: "Fourth, last year in the eighth month Mars entered and left Xuanyuan—release palace women and let them marry as they will." },
  { zh: "五，去年閏十月，有白氣從西方天苑趨參左足，入玉井，恐立秋以後，將有羌寇畔戾之患，宜豫宣告諸郡，嚴為備御。", literal: "Fifth, last year in the intercalary tenth month white vapors from the western Tianyuan rushed toward the left foot of Shen and entered Yujing—fearing that after Beginning of Autumn there may be Qiang raiders rebelling—announce to all commanderies in advance and strictly prepare defense.", idiomatic: "Fifth, last year in the intercalary tenth month white vapors from the western Tianyuan rushed toward the left foot of Shen and entered Yujing—fearing that after Beginning of Autumn Qiang raiders may rebel—announce to all commanderies in advance and strictly prepare defenses." },
  { zh: "六，今月十四日乙卯，白虹貫日，宜令中外官司，並須立秋然後考事。", literal: "Sixth, on the fourteenth of this month, yimao, a white rainbow pierced the sun—order central and external offices to examine affairs only after Beginning of Autumn.", idiomatic: "Sixth, on the fourteenth of this month, yimao, a white rainbow pierced the sun—order central and external offices to examine affairs only after Beginning of Autumn." },
  { zh: "七，漢興以來三百三十九歲，於詩三期，宜大蠲法令，有所變更。", literal: "Seventh, since Han rose it has been three hundred thirty-nine years—in the Odes' three periods—greatly reduce statutes and make changes.", idiomatic: "Seventh, since Han rose it has been three hundred thirty-nine years—in the Odes' three periods—greatly reduce statutes and make changes." },
  { zh: "王者隨天，譬猶自春徂夏，改青服絳也。", literal: "The king follows Heaven, like proceeding from spring to summer, changing green garments for red.", idiomatic: "The king follows Heaven, like proceeding from spring to summer, changing green garments for red." },
  { zh: "自文帝省刑，適三百年，而輕微之禁，漸已殷積。", literal: "From Emperor Wen's reduction of punishments, nearing three hundred years, yet light minor prohibitions have gradually piled up.", idiomatic: "From Emperor Wen's reduction of punishments, nearly three hundred years have passed, yet light minor prohibitions have gradually piled up." },
  { zh: "王者之法，譬猶江、河，當使易避而難犯也。", literal: "The king's law is like the Yangtze and Yellow River—it should be easy to avoid and hard to violate.", idiomatic: "The king's law is like the Yangtze and Yellow River—it should be easy to avoid and hard to violate." },
  { zh: "二月，顗復上書薦黃瓊、李固，以為宜加擢用。", literal: "In the second month, Gu again memorialized recommending Huang Qiong and Li Gu as fitting for special promotion.", idiomatic: "In the second month, Gu again memorialized recommending Huang Qiong and Li Gu as fitting for special promotion." },
  { zh: "又言：「自冬涉春，訖無嘉澤，數有西風，反逆時節，朝廷勞心，廣為禱祈，薦祭山川，暴龍移市。", literal: "He also said: \"From winter through spring there has been no good rain; several times west wind, reversing the seasons—the court labors in heart, widely prays, offers sacrifice to mountains and rivers, exposes the dragon and moves the market.\"", idiomatic: "He also said, \"From winter through spring there has been no good rain; west wind has come several times, reversing the seasons. The court labors in anxiety, widely prays, offers sacrifice to mountains and rivers, exposes the dragon image, and moves the market.\"" },
  { zh: "臣聞皇天感物，不為偽動；", literal: "\"Your servant has heard August Heaven is moved by things, not by pretense;\"", idiomatic: "\"Your servant has heard that August Heaven is moved by things, not by pretense;\"" },
  { zh: "災變應人，要在責己。", literal: "\"prodigies respond to men—the key lies in blaming oneself.\"", idiomatic: "\"prodigies respond to men—the key lies in blaming oneself.\"" },
  { zh: "若令雨可請降，水可攘止，則歲無隔並，太平可待。", literal: "\"If rain could be requested and flood averted, then years without plague would follow and great peace could be awaited.\"", idiomatic: "\"If rain could be requested and flood averted, then years without plague would follow and great peace could be awaited.\"" },
  { zh: "然而災害不息者，患不在此也。", literal: "\"Yet calamities do not cease—the trouble lies not here.\"", idiomatic: "\"Yet calamities do not cease—the trouble lies not here.\"" },
  { zh: "」書奏，特拜郎中；", literal: "The memorial was submitted; he was specially appointed Palace Gentleman;", idiomatic: "The memorial was submitted; he was specially appointed Palace Gentleman;" },
  { zh: "辭病不就。", literal: "he pleaded illness and did not take the post.", idiomatic: "he pleaded illness and did not take the post." },
  { zh: "三月，使匈奴中郎將趙稠遣從事將南匈奴兵出塞擊鮮卑，破之。", literal: "In the third month, the envoy Zhao Chou, Colonel of the Xiongnu, sent staff to lead Southern Xiongnu troops beyond the passes to strike the Xianbei and routed them.", idiomatic: "In the third month, Envoy Zhao Chou, Colonel of the Xiongnu, sent staff to lead Southern Xiongnu troops beyond the passes to strike the Xianbei and routed them." },
  { zh: "初，帝之立也，乳母宋娥與其謀，帝封娥為山陽君，又封執金吾梁商子冀為襄邑侯。", literal: "Initially when the Emperor was established, wet nurse Song E shared in the plotting; the Emperor enfeoffed E as Lady of Shanyang, and also enfeoffed Liang Ji's son as Marquis of Xiangyi.", idiomatic: "Initially when the Emperor was established, wet nurse Song E shared in the plotting. The Emperor enfeoffed E as Lady of Shanyang and also enfeoffed Liang Ji's son as Marquis of Xiangyi." },
  { zh: "尚書令左雄上封事曰：「高皇帝約，非劉氏不王，非有功不侯。", literal: "Director of the Secretariat Zuo Xiong submitted a sealed memorial, saying: \"Founding Emperor's covenant—none but Liu to be king, none without merit to be marquis.\"", idiomatic: "Director of the Secretariat Zuo Xiong submitted a sealed memorial, saying, \"The Founding Emperor's covenant: none but Liu to be king, none without merit to be marquis.\"" },
  { zh: "孝安皇帝封江京、王聖等，遂致地震之異。", literal: "\"Emperor An enfeoffed Jiang Jing, Wang Sheng, and others, and thus brought earthquake prodigies.\"", idiomatic: "\"Emperor An enfeoffed Jiang Jing, Wang Sheng, and others, and thus brought earthquake prodigies.\"" },
  { zh: "永建二年封陰謀之功，又有日食之變。", literal: "\"In Yongjian year 2 enfeoffing those of secret plotting also brought solar eclipse changes.\"", idiomatic: "\"In Yongjian year 2, enfeoffing those who had plotted in secret also brought solar eclipse prodigies.\"" },
  { zh: "數術之士，咸歸咎於封爵。", literal: "\"Men of numerology all attributed it to enfeoffment.\"", idiomatic: "\"Men of numerology all attributed it to enfeoffment.\"" },
  { zh: "今青州饑虛，盜賊未息，誠不宜追尋小恩，虧失大典。", literal: "\"Now Qingzhou is famine-struck and empty, bandits not yet quelled—truly inappropriate to chase small favors and lose the great canon.\"", idiomatic: "\"Now Qingzhou is famine-struck and empty and bandits are not yet quelled—it is truly inappropriate to chase small favors and lose the great canon.\"" },
  { zh: "」詔不聽。", literal: "The edict did not listen.", idiomatic: "The edict was not heeded." },
  { zh: "雄復諫曰：「臣聞人君莫不好忠正而惡讒諛，然而歷世之患，莫不以忠正得罪，讒諛蒙幸者，蓋聽忠難，從諛易也。", literal: "Xiong remonstrated again, saying: \"Your servant has heard that rulers all love loyalty and straightness and hate slander and flattery, yet through the ages the trouble has always been that the loyal and straight are punished while slanderers and flatterers receive favor—probably because hearing loyalty is hard and following flattery is easy.\"", idiomatic: "Xiong remonstrated again, saying, \"Your servant has heard that rulers all love loyalty and straightness and hate slander and flattery, yet through the ages the trouble has always been that the loyal and straight are punished while slanderers and flatterers receive favor—probably because hearing loyalty is hard and following flattery is easy.\"" },
  { zh: "夫刑罪，人情之所甚惡，貴寵，人情之所甚欲，是以時俗為忠者少而習諛者多。", literal: "\"Punishment and penalty are what human feelings greatly loathe; noble favor is what human feelings greatly desire—thus in the times those who act loyal are few and those who practice flattery are many.\"", idiomatic: "\"Punishment and penalty are what people greatly loathe; noble favor is what people greatly desire—thus in the times those who act loyal are few and those who practice flattery are many.\"" },
  { zh: "故令人主數聞其美，稀知其過，迷而不悟，以至於危亡。", literal: "\"Therefore rulers often hear their own praise and rarely know their faults, wander without awakening, and reach ruin.\"", idiomatic: "\"Therefore rulers often hear their own praise and rarely know their faults, wander without awakening, and reach ruin.\"" },
  { zh: "臣伏見詔書，顧念阿母舊德宿恩，欲特加顯賞。", literal: "\"Your servant has seen the edict, recalling foster mother's old virtue and long-standing grace, wishing to add special conspicuous reward.\"", idiomatic: "\"Your servant has seen the edict, recalling the foster mother's old virtue and long-standing grace and wishing to add special conspicuous reward.\"" },
  { zh: "案尚書故事，無乳母爵邑之制，唯先帝時阿母王聖為野王君，聖造生讒賊廢立之禍，生為天下所咀嚼，死為海內所歡快。", literal: "\"Checking Secretariat precedents, there is no institution of rank and fief for wet nurses—only under the former emperor foster mother Wang Sheng was made Lady of Yewang. Sheng gave birth to slanderers and the calamity of deposition and establishment; alive she was chewed over by all under heaven, dead she was rejoiced over within the seas.\"", idiomatic: "\"Checking Secretariat precedents, there is no institution of rank and fief for wet nurses—only under the former emperor foster mother Wang Sheng was made Lady of Yewang. Sheng gave birth to slanderers and the calamity of deposition and establishment; alive she was reviled by all under heaven, dead she was rejoiced over within the seas.\"" },
  { zh: "桀、紂貴為天子，而庸僕羞與為比者，以其無義也；", literal: "\"Jie and Zhou were exalted as Sons of Heaven, yet common servants were ashamed to be compared with them because they lacked righteousness;\"", idiomatic: "\"Jie and Zhou were exalted as Sons of Heaven, yet common servants were ashamed to be compared with them because they lacked righteousness;\"" },
  { zh: "夷、齊賤為匹夫，而王侯爭與為伍者，以其有德也。", literal: "\"Bo Yi and Shu Qi were base as commoners, yet kings and marquises competed to join their company because they had virtue.\"", idiomatic: "\"Bo Yi and Shu Qi were base as commoners, yet kings and marquises competed to join their company because they had virtue.\"" },
  { zh: "今阿母躬蹈儉約，以身率下，群僚蒸庶，莫不向風。", literal: "\"Now the foster mother personally practices thrift and restraint, leading those below by her person; officials and the masses all turn toward her wind.\"", idiomatic: "\"Now the foster mother personally practices thrift and restraint and leads those below by her example; officials and the masses all turn toward her example.\"" },
  { zh: "而與王聖並同爵號，懼違本操，失其常願。", literal: "\"Yet to share rank and title with Wang Sheng—I fear violating her original conduct and losing her constant wish.\"", idiomatic: "\"Yet to share rank and title with Wang Sheng—I fear she would violate her original conduct and lose her constant wish.\"" },
  { zh: "臣愚以為凡人之心，理不相遠，其所不安，古今一也。", literal: "\"Your servant foolishly holds that the hearts of ordinary men, in principle, are not far apart; what unsettles them is the same in antiquity and today.\"", idiomatic: "\"Your servant foolishly holds that ordinary men's hearts, in principle, are not far apart; what unsettles them is the same in antiquity and today.\"" },
  { zh: "百姓深懲王聖傾覆之禍，民萌之命危於累卵，常懼時世復有此類，怵惕之念未離於心，恐懼之言未絕乎口。", literal: "\"The people deeply punish Wang Sheng's overturning calamity; the common folk's lives were precarious as piled eggs—they constantly fear the age will again have such a type; thoughts of dread have not left their hearts, words of fear have not ceased from their mouths.\"", idiomatic: "\"The people deeply punish Wang Sheng's overturning calamity; the common folk's lives were precarious as piled eggs. They constantly fear the age will again produce such a case; thoughts of dread have not left their hearts and words of fear have not ceased from their mouths.\"" },
  { zh: "乞如前議，歲以千萬給奉阿母，內足以盡恩愛之歡，外可不為吏民所怪。", literal: "\"I beg as in the former proposal: yearly grant ten million for the foster mother's support—inwardly enough to fulfill affection's joy, outwardly not strange to officials and people.\"", idiomatic: "\"I beg as in the former proposal: grant ten million yearly for the foster mother's support—inwardly enough to fulfill affection's joy, outwardly not strange to officials and people.\"" },
  { zh: "梁冀之封，事非機急，宜過災顧之運，然後平議可否。", literal: "\"Liang Ji's enfeoffment is not urgent in the matter—it should pass the period when prodigies are watched, then calmly debate whether it is permissible.\"", idiomatic: "\"Liang Ji's enfeoffment is not an urgent matter—it should wait until the period when prodigies are watched has passed, then calmly debate whether it is permissible.\"" },
  { zh: "」於是冀父商讓還冀封；", literal: "Thereupon Ji's father Shang yielded and returned Ji's fief;", idiomatic: "Thereupon Ji's father Shang yielded and returned Ji's fief;" },
  { zh: "書十餘上，帝乃從之。", literal: "more than ten memorials were submitted before the Emperor followed.", idiomatic: "more than ten memorials were submitted before the Emperor consented." },
  { zh: "夏，四月，己亥，京師地震。", literal: "In summer, the fourth month, on jihai day, the capital had an earthquake.", idiomatic: "In summer, in the fourth month, on jihai day, the capital had an earthquake." },
  { zh: "五月，庚子，詔群公、卿士各直言厥咎，仍各舉敦樸士一人。", literal: "In the fifth month, on gengzi day, an edict ordered all dukes and ministers to speak plainly of their faults, and each also to recommend one plain and honest gentleman.", idiomatic: "In the fifth month, on gengzi day, an edict ordered all dukes and ministers to speak plainly of their faults, and each also to recommend one plain and honest gentleman." },
  { zh: "左雄復上疏曰：「先帝封野王君，漢陽地震，今封山陽君而京城復震，專政在陰，其災尤大。", literal: "Zuo Xiong again memorialized, saying: \"The former emperor enfeoffed Lady of Yewang and Hanyang had an earthquake; now enfeofing Lady of Shanyang and the capital again quakes—exclusive government lies in yin, and the calamity is especially great.\"", idiomatic: "Zuo Xiong again memorialized, saying, \"The former emperor enfeoffed Lady of Yewang and Hanyang had an earthquake; now enfeofing Lady of Shanyang and the capital again quakes—exclusive government lies in yin, and the calamity is especially great.\"" },
  { zh: "臣前後瞽言，封爵至重，王者可私人以財，不可以官，宜還阿母之封以塞災異。", literal: "\"Your servant's successive blind words: enfeoffment is extremely weighty—the king may give a person private wealth, not office; the foster mother's fief should be returned to block prodigies.\"", idiomatic: "\"Your servant's successive blind words: enfeoffment is extremely weighty—the king may give a person private wealth, not office. The foster mother's fief should be returned to block prodigies.\"" },
  { zh: "今冀已高讓，山陽君亦宜崇其本節。", literal: "\"Now Ji has loftily yielded; Lady of Shanyang should also honor her original integrity.\"", idiomatic: "\"Now Ji has loftily yielded; Lady of Shanyang should also honor her original integrity.\"" },
  { zh: "」雄言切至，娥亦畏懼辭讓。", literal: "Xiong's words were sharp and thorough; E also feared and pleaded to yield.", idiomatic: "Xiong's words were sharp and thorough; E also feared and pleaded to yield." },
  { zh: "而帝戀戀不能已，卒封之。", literal: "Yet the Emperor clung fondly and could not stop; in the end he enfeoffed her.", idiomatic: "Yet the Emperor clung fondly and could not stop; in the end he enfeoffed her." },
  { zh: "是時，大司農劉據以職事被譴，召詣尚書，傳呼促步，又加以捶撲。", literal: "At this time Grand Minister of Agriculture Liu Ju was reprimanded for official matters, summoned to the Secretariat, urged by criers to quicken his step, and also given beating and flogging.", idiomatic: "At this time Grand Minister of Agriculture Liu Ju was reprimanded for official matters, summoned to the Secretariat, urged by criers to quicken his step, and also beaten and flogged." },
  { zh: "雄上言：「九卿位亞三事，班在大臣，行有佩玉之節，動有癢序之儀。", literal: "Xiong memorialized, saying: \"The Nine Ministers rank next to the three duties, classed among great ministers; in walking they have the ritual of jade pendants, in movement the ceremony of itch-and-order.\"", idiomatic: "Xiong memorialized, saying, \"The Nine Ministers rank next to the three duties and are classed among great ministers; in walking they have the ritual of jade pendants and in movement the ceremony of ranked precedence.\"" },
  { zh: "孝明皇帝始有撲罰，皆非古典。", literal: "\"Emperor Ming first had beating punishment—none of this is ancient canon.\"", idiomatic: "\"Emperor Ming first had beating punishment—none of this is ancient canon.\"" },
  { zh: "」帝納之，是後九卿無復捶撲者。", literal: "The Emperor accepted it; thereafter the Nine Ministers were no longer beaten and flogged.", idiomatic: "The Emperor accepted it; thereafter the Nine Ministers were no longer beaten and flogged." },
  { zh: "戊午，司空王龔免。", literal: "On wuwu day, Minister of Works Wang Gong was dismissed.", idiomatic: "On wuwu day, Minister of Works Wang Gong was dismissed." },
  { zh: "六月，辛未，以太常魯國孔扶為司空。", literal: "In the sixth month, on xinwei day, made Director of Ceremonies Kong Fu of Lu Grand Minister of Works.", idiomatic: "In the sixth month, on xinwei day, Director of Ceremonies Kong Fu of Lu was made Minister of Works." },
  { zh: "丁丑，洛陽宣德亭地坼，長八十五丈；", literal: "On dingchou day, the ground split at Xuande pavilion in Luoyang, eighty-five zhang long;", idiomatic: "On dingchou day, the ground split at Xuande pavilion in Luoyang, eighty-five zhang long;" },
  { zh: "帝引公卿所舉敦樸之士，使之對策，及特問以當世之敝，為政所宜。", literal: "the Emperor summoned the plain and honest gentlemen recommended by dukes and ministers, had them answer policy questions, and specially asked about present-day ills and what government should do.", idiomatic: "the Emperor summoned the plain and honest gentlemen recommended by dukes and ministers, had them answer policy questions, and specially asked about present-day ills and what government should do." },
  { zh: "李固對曰：「前孝安皇帝變亂舊典，封爵阿母，因造妖孽，改亂嫡嗣，至令聖躬狼狽，親遇其艱。", literal: "Li Gu replied, saying: \"Formerly Emperor An overturned old canons, enfeoffed the foster mother, thereby creating prodigies, altered and confused the legitimate heir, until the sage person was in distress and personally met hardship.\"", idiomatic: "Li Gu replied, saying, \"Formerly Emperor An overturned old canons, enfeoffed the foster mother, thereby creating prodigies, and altered and confused the legitimate heir, until Your Majesty was in distress and personally met hardship.\"" },
  { zh: "既拔自困殆，龍興即位，天下喁喁，屬望風政。", literal: "\"Having been raised from peril, the dragon arose and took the throne; all under heaven murmured and looked to your wind in government.\"", idiomatic: "\"Having been raised from peril, you arose and took the throne; all under heaven murmured and looked to your governance.\"" },
  { zh: "積敝之後，易致中興，誠當沛然思惟善道，而論者猶云『方今之事，復同於前』。", literal: "\"After accumulated ills, renewal is easy to bring—truly one should abundantly think on the good Way, yet debaters still say 'affairs today are again the same as before.'\"", idiomatic: "\"After accumulated ills, renewal is easy to bring—truly one should abundantly think on the good Way, yet debaters still say 'affairs today are again the same as before.'\"" },
  { zh: "臣伏在草澤，痛心傷臆！", literal: "\"Your servant lies low in grass and marsh, heart pained and breast wounded!\"", idiomatic: "\"Your servant lies low in grass and marsh, heart pained and breast wounded!\"" },
  { zh: "實以漢興以來三百餘年，賢聖相繼十有八主，豈無阿乳之恩，豈忘貴爵之寵？", literal: "\"Truly since Han rose more than three hundred years, worthy sages succeeding one another for eighteen rulers—was there no foster-mother affection, was noble rank's favor forgotten?\"", idiomatic: "\"Truly since Han rose more than three hundred years, worthy sages succeeding one another through eighteen rulers—was there no foster-mother affection? Was noble rank's favor forgotten?\"" },
  { zh: "然上畏天威，俯案經典，知義不可，故不封也。", literal: "\"Yet they revered Heaven's majesty above, bowed to the classics below, knew righteousness forbade it, and therefore did not enfeoff.\"", idiomatic: "\"Yet they revered Heaven's majesty above, bowed to the classics below, knew righteousness forbade it, and therefore did not enfeoff.\"" },
  { zh: "今宋阿母雖有大功、勤謹之德，但加賞賜，足以酬其勞苦；", literal: "\"Now Foster Mother Song, though she has great merit and diligent, careful virtue—only add rewards and gifts, enough to repay her toil;\"", idiomatic: "\"Now Foster Mother Song, though she has great merit and diligent, careful virtue—only add rewards and gifts, enough to repay her toil;\"" },
  { zh: "至於裂土開國，實乖舊典。", literal: "\"as for splitting land and opening a state, it truly violates old canon.\"", idiomatic: "\"as for splitting land and opening a state, it truly violates old canon.\"" },
  { zh: "聞阿母體性謙虛，必有遜讓，陛下宜許其辭國之高，使成萬安之福。", literal: "\"I hear the foster mother's nature is modest—she will surely yield; Your Majesty should permit her lofty refusal of a state and thereby complete the blessing of ten thousand peace.\"", idiomatic: "\"I hear the foster mother's nature is modest—she will surely yield. Your Majesty should permit her lofty refusal of a state and thereby secure the blessing of lasting peace.\"" },
  { zh: "夫妃、後之家所以少完全者，豈天性當然？", literal: "\"That consort and empress families rarely end whole—is it their nature that it must be so?\"", idiomatic: "\"That consort and empress families rarely end whole—is it their nature that it must be so?\"" },
  { zh: "但以爵位尊顯，顓總權柄，天道惡盈，不知自損，故致顛仆。", literal: "\"Only because rank and position are exalted, they monopolize authority; Heaven's Way hates fullness—they do not know self-reduction, and therefore fall.\"", idiomatic: "\"Only because rank and position are exalted, they monopolize authority. Heaven's Way hates fullness—they do not know self-reduction, and therefore fall.\"" },
  { zh: "先帝寵遇閻氏，位號太疾，故其受禍曾不旋時，《老子》曰：『其進銳者其退速也。", literal: "\"The former emperor favored the Yan clan, rank and title too swift—thus their receiving calamity did not wait a turn of the hour. Laozi says: 'What advances sharply retreats swiftly.'\"", idiomatic: "\"The former emperor favored the Yan clan and advanced rank and title too swiftly—thus their receiving calamity did not wait a turn of the hour. Laozi says, 'What advances sharply retreats swiftly.'\"" },
  { zh: "』今梁氏戚為椒房，禮所不臣，尊以高爵，尚可然也；", literal: "\"Now the Liang clan as kin of the inner chamber are what ritual does not make subjects—honoring them with high rank can still be so;\"", idiomatic: "\"Now the Liang clan as kin of the inner chamber are what ritual does not make subjects—honoring them with high rank can still be acceptable;\"" },
  { zh: "而子弟群從，榮顯兼加，永平、建初故事，殆不如此。", literal: "\"yet sons, younger brothers, and the whole lineage together add glory and display—the precedents of Yongping and Jianchu scarcely went this far.\"", idiomatic: "\"yet sons, younger brothers, and the whole lineage together add glory and display—the precedents of Yongping and Jianchu scarcely went this far.\"" },
  { zh: "宜令步兵校尉冀及諸侍中還居黃門之官，使權去外戚，政歸國家，豈不休乎！", literal: "It would be fitting to have Infantry Commandant Ji and the various Palace Attendants return to their Yellow Gate offices, so that power leaves the maternal kin and government returns to the state—would that not be excellent!", idiomatic: "It would be fitting to have Infantry Commandant Liang Ji and the various Palace Attendants return to their Yellow Gate offices, so that power leaves the maternal kin and government returns to the state—would that not be excellent!" },
  { zh: "又，詔書所以禁侍中、尚書、中臣子弟不得為吏、察孝廉者，以其秉威權，容請托故也。", literal: "Moreover, the reason edicts forbid sons of Palace Attendants, Directors of the Secretariat, and inner eunuchs from holding office or being nominated as Filial and Incorrupt is that they wield authority and favor and accept private requests.", idiomatic: "Moreover, edicts forbid sons of Palace Attendants, Directors of the Secretariat, and inner eunuchs from holding office or being nominated as Filial and Incorrupt because they wield authority and accept private requests." },
  { zh: "而中常侍在日月之側，聲勢振天下，子弟祿任，曾無限極，雖外托謙默，不干州郡，而諂偽之徒，望風進舉。", literal: "Yet the Regular Palace Attendants stand beside the sun and moon; their voices and power shake all under heaven; their sons and younger kin receive salaries and appointments without limit. Though outwardly they profess humility and do not meddle in the provinces, flatterers and frauds advance at the wind of their reputation.", idiomatic: "Yet the Regular Palace Attendants stand beside the throne; their voices and power shake all under heaven, and their sons and younger kin receive salaries and appointments without limit. Though outwardly they profess humility and do not meddle in the provinces, flatterers and frauds advance at the wind of their reputation." },
  { zh: "今可為設常禁，同之中臣。", literal: "Now one may set a standing prohibition, applying the same rule to inner eunuchs.", idiomatic: "Now one may set a standing prohibition, applying the same rule to inner eunuchs." },
  { zh: "昔館陶公主為子求郎，明帝不許，賜錢千萬，所以輕厚賜，重薄位者，為官人失才，害及百姓也。", literal: "Formerly when Princess Guantao sought a Gentleman rank for her son, Emperor Ming did not grant it but gave ten million cash—the reason heavy thick gifts were used to value thin offices lightly was that placing the unworthy in office harms the people.", idiomatic: "Formerly when Princess Guantao sought a Gentleman rank for her son, Emperor Ming refused but gave ten million cash—the reason he lavished gifts yet withheld office lightly was that placing the unworthy in office harms the people." },
  { zh: "竊聞長水司馬武宣、開陽城門候羊迪等，無它功德，初拜便真，此雖小失而漸壞舊章。", literal: "I have heard that Commander of the Chang River Wu Xuan, Gatekeeper of Kaiyang Yang Di, and others, without other merit or virtue, upon first appointment received full regular salary—though a small lapse, it gradually ruins the old regulations.", idiomatic: "I have heard that Commander of the Chang River Wu Xuan, Gatekeeper of Kaiyang Yang Di, and others, without other merit or virtue, upon first appointment received full regular salary—though a small lapse, it gradually ruins the old regulations." },
  { zh: "先聖法度，所宜堅守，故政教一跌，百年不復。", literal: "The laws and institutions of the former sages ought to be firmly held; once government and teaching stumble, a hundred years will not restore them.", idiomatic: "The laws and institutions of the former sages ought to be firmly held; once government and teaching stumble, a hundred years will not restore them." },
  { zh: "《詩》云：『上帝板板，下民卒癉』，刺周王變祖法度，故使下民將盡病也。", literal: "The Odes says: \"High God is topsy-turvy, the lower people will utterly sicken\"—criticizing the Zhou king for changing ancestral law, causing the people below to be nearly all ill.", idiomatic: "The Odes says, \"High God is topsy-turvy, the lower people will utterly sicken\"—criticizing the Zhou king for changing ancestral law and causing the people below to be nearly all ill." },
  { zh: "今陛下之有尚書，猶天之有北斗也。", literal: "Now that Your Majesty has Directors of the Secretariat is like heaven having the Northern Dipper.", idiomatic: "That Your Majesty has Directors of the Secretariat is like heaven having the Northern Dipper." },
  { zh: "斗為天喉舌，尚書亦為陛下喉舌。", literal: "The Dipper is heaven's throat and tongue; the Directors are also Your Majesty's throat and tongue.", idiomatic: "The Dipper is heaven's throat and tongue; the Directors are also Your Majesty's throat and tongue." },
  { zh: "斗斟酌元氣，運乎四時；", literal: "The Dipper measures out primordial qi and moves through the four seasons;", idiomatic: "The Dipper measures out primordial qi and moves through the four seasons;" },
  { zh: "尚書出納王命，賦政四海，權尊勢重，責之所歸，若不平心，災眚必至，誠宜審擇其人，以毘聖政。", literal: "Directors receive and issue the king's commands and assign government to the four seas—with exalted authority and heavy power, responsibility rests on them; if they do not balance their hearts, calamities must come—truly one should carefully choose such men to assist sage government.", idiomatic: "Directors receive and issue the king's commands and assign government to the four seas. With exalted authority and heavy power, responsibility rests on them; if they do not balance their hearts, calamities must come—Your Majesty should carefully choose such men to assist sage government." },
  { zh: "今與陛下共天下者，外則公、卿、尚書，內則常侍、黃門，譬猶一門之內，一家之事，安則共其福慶，危則通其禍敗。", literal: "Those who today share the realm with Your Majesty are outwardly the Excellencies, Directors, inwardly the Regular Attendants and Yellow Gate—as in one gate's household, one family's affairs; in peace they share fortune and blessing, in danger they share misfortune and ruin.", idiomatic: "Those who today share the realm with Your Majesty are outwardly the Excellencies and Directors, inwardly the Regular Attendants and Yellow Gate—as in one household within one gate; in peace they share fortune and blessing, in danger they share misfortune and ruin." },
  { zh: "刺史、二千石，外統職事，內受法則。", literal: "Inspectors and the two-thousand-dan officials outwardly oversee official duties, inwardly receive law and norms.", idiomatic: "Inspectors and the two-thousand-dan officials outwardly oversee official duties and inwardly receive law and norms." },
  { zh: "夫表曲者景必邪，源清者流必潔，猶叩樹本，百枝皆動也。", literal: "When the gnomon's shadow is crooked the image must be slant; when the source is clear the stream must be pure—like knocking the tree's trunk, a hundred branches all move.", idiomatic: "When the sundial's shadow is crooked the image must be slant; when the source is clear the stream must be pure—like knocking the tree's trunk, a hundred branches all move." },
  { zh: "由此言之，本朝號令，豈可蹉跌！", literal: "From this it is said: can the court's orders and proclamations stumble!", idiomatic: "From this it follows: can the court's orders and proclamations stumble!" },
  { zh: "天下之紀綱，當今之急務也。", literal: "The cords and net of all under heaven are the urgent business of the present age.", idiomatic: "The cords and net of all under heaven are the urgent business of the present age." },
  { zh: "夫人君之有政，猶水之有堤坊。", literal: "When a lord has government it is like water having dikes and embankments.", idiomatic: "When a lord has government it is like water having dikes and embankments." },
  { zh: "堤坊完全，雖遭雨水霖潦，不能為變。", literal: "When dikes are complete, though encountering great rain and flood, it cannot change.", idiomatic: "When dikes are complete, though great rain and flood come, they cannot change it." },
  { zh: "政教一立，暫遭凶年，不足為憂。", literal: "Once government and teaching are established, though temporarily meeting a bad year, it is insufficient for worry.", idiomatic: "Once government and teaching are established, though a bad year comes temporarily, it is not worth worry." },
  { zh: "誠令堤防穿漏，萬夫同力，不能復救；", literal: "Truly if the dike defenses are pierced and leaking, ten thousand men with united strength cannot rescue;", idiomatic: "Truly if the dike defenses are pierced and leaking, ten thousand men with united strength cannot rescue them;" },
  { zh: "政教一壞，賢智馳鶩，不能復還。", literal: "once government and teaching are ruined, the worthy and wise scatter in flight and cannot return.", idiomatic: "once government and teaching are ruined, the worthy and wise scatter in flight and cannot return." },
  { zh: "今堤防雖堅，漸有孔穴。", literal: "Now the dike defenses though solid gradually have holes and cracks.", idiomatic: "Now the dike defenses, though solid, gradually have holes and cracks." },
  { zh: "譬之一人之身，本朝者，心腹也，州、郡者，四支也，心腹痛則四支不舉。", literal: "It is like one person's body—the court is the heart and belly, the provinces and commanderies are the four limbs; when heart and belly are in pain the four limbs do not lift.", idiomatic: "It is like one person's body—the court is the heart and belly, the provinces and commanderies are the four limbs; when heart and belly are in pain the four limbs do not lift." },
  { zh: "故臣之所憂，在腹心之疾，非四支之患也。", literal: "Thus what your servant worries about is disease of heart and belly, not ailment of the four limbs.", idiomatic: "Thus what your servant worries about is disease of heart and belly, not ailment of the four limbs." },
  { zh: "苟堅堤防，務政教，先安心腹，整理本朝，雖有寇賊、水旱之變，不足介意也；", literal: "If one firmly builds dikes, devotes effort to government and teaching, first securing heart and belly and putting the court in order, though there be bandits and flood or drought changes, it is not worth minding;", idiomatic: "If one firmly builds dikes, devotes effort to government and teaching, first secures heart and belly and puts the court in order, though bandits and flood or drought come, it is not worth minding;" },
  { zh: "誠令堤防壞漏，心腹有疾，雖無水旱之災，天下固可以憂矣。", literal: "truly if dike defenses break and leak and heart and belly have disease, though there be no flood or drought disaster, the realm can still be worried over.", idiomatic: "truly if dike defenses break and leak and heart and belly have disease, though there is no flood or drought disaster, the realm can still be cause for worry." },
  { zh: "又宜罷退宦官，去其權重，裁置常侍二人方直有德者省事左右，小黃門五人才智閑雅者給事殿中。", literal: "Further one should dismiss and demote eunuchs, remove their heavy authority, limit to two Regular Palace Attendants of upright square virtue handling affairs at left and right, five Junior Yellow Gate men of talent, wisdom, leisure, and elegance serving in the hall.", idiomatic: "Further one should dismiss and demote eunuchs and remove their heavy authority, limiting Regular Palace Attendants to two upright men of virtue handling affairs at left and right, and five Junior Yellow Gate men of talent, wisdom, and refined manner to serve in the hall." },
  { zh: "如此，則論者厭塞，昇平可致也！", literal: "Thus disputants would be satisfied and stopped, and ascending peace could be attained!", idiomatic: "Thus disputants would be satisfied and stopped, and an age of ascending peace could be attained!" },
  { zh: "扶風功曹馬融對曰：「今科條品制，四時禁令，所以承天順民者，備矣，悉矣，不可加矣。", literal: "Ma Rong, Merit Officer of Fufeng, replied: \"Now statutes and grades, the four seasons' prohibitions, what receives heaven and accords with the people—all is provided, all is complete, nothing can be added.", idiomatic: "Ma Rong, Merit Officer of Fufeng, replied, \"Now statutes and grades and the four seasons' prohibitions—what receives heaven and accords with the people—is all provided and complete; nothing can be added." },
  { zh: "然而天猶有不平之效，民猶有咨嗟之怨者，百姓屢聞恩澤之聲，而未見惠和之實也。", literal: "Yet heaven still has unbalanced effects, the people still have sighing complaints—the common people often hear the sound of grace but do not see the substance of benefit and harmony.", idiomatic: "Yet heaven still shows imbalance, and the people still sigh in complaint—the common people often hear the sound of grace but do not see the substance of benefit and harmony." },
  { zh: "古之足民者，非能家贍而人足之，量其財用，為之制度。", literal: "Those of antiquity who made the people sufficient did not make every household rich so every man was full—they measured out resources and expenditure and made institutions for them.", idiomatic: "Those of antiquity who made the people sufficient did not make every household rich so every man was full—they measured resources and expenditure and made institutions for them." },
  { zh: "故嫁娶之禮儉，則婚者以時矣；", literal: "Thus if marriage rites were frugal, those marrying did so in season;", idiomatic: "Thus if marriage rites were frugal, those marrying did so in season;" },
  { zh: "喪制之禮約，則終者掩藏矣；", literal: "if mourning rites were restrained, those dying were buried and concealed;", idiomatic: "if mourning rites were restrained, the dead were buried and concealed;" },
  { zh: "不奪其時，則農夫利矣。", literal: "if their seasons were not seized, farmers profited.", idiomatic: "if their seasons were not seized, farmers profited." },
  { zh: "夫妻子以累其心，產業以重其志，捨此而為非者，有必不多矣！", literal: "Wife and children to burden the heart, property and estates to weigh the ambition—abandon this and do wrong and there cannot be many!", idiomatic: "Wife and children burden the heart and property and estates weigh the ambition—abandon this and do wrong and there cannot be many!" },
  { zh: "太史令南陽張衡對曰：「自初舉孝廉，迄今二百歲矣，皆先孝行；", literal: "Grand Clerk Zhang Heng of Nanyang replied: \"Since the first raising of Filial and Incorrupt, to now two hundred years have passed—all first had filial conduct;", idiomatic: "Grand Clerk Zhang Heng of Nanyang replied, \"Since the first raising of Filial and Incorrupt, two hundred years have passed—all first required filial conduct;" },
  { zh: "行有餘力，始學文法。", literal: "when conduct had surplus strength, only then they studied literary law.", idiomatic: "when conduct had surplus strength, only then they studied literary law." },
  { zh: "辛卯詔書，以能章句、奏案為限；", literal: "The xinmao edict took ability at clause commentary and memorial drafting as the limit;", idiomatic: "The xinmao edict took ability at clause commentary and memorial drafting as the limit;" },
  { zh: "雖有至孝，猶不應科，此棄本而取末。", literal: "though there was utmost filial piety, still they did not meet the category—this abandons root and takes branch.", idiomatic: "though there was utmost filial piety, still they did not meet the category—this abandons root and takes branch." },
  { zh: "曾子長於孝，然實魯鈍，文學不若游、夏，政事不若冉、季。", literal: "Zengzi excelled in filial piety but was truly dull in Lu; literary studies not like You or Xia, government affairs not like Ran or Ji.", idiomatic: "Zengzi excelled in filial piety but was truly dull in Lu; in literary studies he did not match You or Xia, in government affairs he did not match Ran or Ji." },
  { zh: "今欲使一人兼之，苟外有可觀，內必有闕，則違選舉孝廉之志矣。", literal: "Now wishing one man to combine all—if outwardly there is something to view, inwardly there must be lacks—then it violates the intent of selecting Filial and Incorrupt.", idiomatic: "Now wishing one man to combine all—if outwardly there is something to view, inwardly there must be lacks—then it violates the intent of selecting Filial and Incorrupt." },
  { zh: "且郡國守相，剖符寧境，為國大臣，一旦免黜十有餘人，吏民罷於送迎之役，新故交際，公私放濫，或臨政為百姓所便而以小過免之，是為奪民父母使嗟號也。", literal: "Moreover the commandery and state governors and chancellors, splitting tallies and securing the border as great ministers of the state—once more than ten were dismissed; clerks and people were exhausted by seeing-off and receiving duties; new and old alternated, public and private overflowed—some were convenient to the people in governing yet dismissed for small faults—that is seizing the people's parents and making them wail.", idiomatic: "Moreover the commandery and state governors and chancellors, who split tallies and secure the border as great ministers of the state—once more than ten were dismissed at a stroke. Clerks and people were exhausted by seeing-off and receiving duties; new and old alternated and public and private affairs overflowed. Some who governed conveniently for the people were dismissed for small faults—that is seizing the people's parents and making them wail." },
  { zh: "《易》不遠復，《論》不憚改，朋友交接且不宿過，況於帝王，承天理物，以天下為公者乎！", literal: "The Changes says not distant from restoration, the Analects says not fearing to change—friends in contact do not even lodge overnight over faults—how much more the Son of Heaven, receiving heaven's principle and things, taking the realm as public!", idiomatic: "The Changes says not distant from restoration, the Analects says not fearing to change—even friends in contact do not lodge overnight over faults. How much more the Son of Heaven, who receives heaven's principle and governs things and takes the realm as public!" },
  { zh: "中間以來，妖星見於上，震裂著於下，天誡詳矣，可為寒心。", literal: "In the interval prodigious stars have appeared above, earthquakes and cracks shown below—heaven's warning is detailed; one may feel cold at heart.", idiomatic: "In the interval prodigious stars have appeared above and earthquakes and cracks below—heaven's warning is detailed and should make one feel cold at heart." },
  { zh: "明者消禍於未萌。", literal: "The enlightened extinguish calamity before it sprouts.", idiomatic: "The enlightened extinguish calamity before it sprouts." },
  { zh: "今既見矣，修政恐懼，則禍轉為福矣。", literal: "Now that it has been seen, to repair government in fear and dread—then calamity turns to blessing.", idiomatic: "Now that it has been seen, to repair government in fear and dread—then calamity turns to blessing." },
  { zh: "上覽眾對，以李固為第一，即時出阿母還捨，諸常侍悉叩頭謝罪，朝廷肅然。", literal: "The Emperor reviewed the various replies, ranked Li Gu first, immediately sent the foster mother back to her quarters, all Regular Palace Attendants kowtowed begging pardon, and the court was solemn.", idiomatic: "The Emperor reviewed the various replies and ranked Li Gu first. He immediately sent the foster mother back to her quarters; all Regular Palace Attendants kowtowed begging pardon, and the court was solemn." },
  { zh: "以固為議郎；", literal: "Made Gu Remonstrating Censor;", idiomatic: "Li Gu was made Remonstrating Censor;" },
  { zh: "而阿母、宦者皆疾之，詐為飛章以陷其罪。", literal: "yet the foster mother and eunuchs all hated him, fabricating flying memorials to trap him in guilt.", idiomatic: "yet the foster mother and eunuchs all hated him and fabricated anonymous memorials to trap him in guilt." },
  { zh: "事從中下，大司農南郡黃尚等請之於梁商，僕射黃瓊復救明其事。", literal: "The matter followed the palace attendant's downward transmission; Grand Minister of Agriculture Huang Shang of Nan commandery and others requested on his behalf from Liang Shang, Vice Director Huang Qiong again clarified the matter.", idiomatic: "The matter followed the palace attendant's secret channel downward. Grand Minister of Agriculture Huang Shang of Nan commandery and others pleaded on his behalf to Liang Shang, and Vice Director Huang Qiong again clarified the matter." },
  { zh: "久乃得釋，出為洛令，固棄官歸漢中。", literal: "Only after long time was he released, sent out as Magistrate of Luo—Gu abandoned office and returned to Hanzhong.", idiomatic: "Only after a long time was he released and sent out as Magistrate of Luo. Gu abandoned office and returned to Hanzhong." },
  { zh: "融博通經籍，美文辭；", literal: "Rong was broadly versed in the classics, fine in literary compositions;", idiomatic: "Rong was broadly versed in the classics and fine in literary composition;" },
  { zh: "對奏，亦拜議郎。", literal: "for his reply memorial he was also made Remonstrating Censor.", idiomatic: "for his reply memorial he was also made Remonstrating Censor." },
  { zh: "衡善屬文，通貫《六藝》，雖才高於世，而無驕尚之情；", literal: "Heng was skilled at literary composition, thoroughly mastered the Six Arts—though talent higher than the age, without arrogant esteeming disposition;", idiomatic: "Heng was skilled at literary composition and thoroughly mastered the Six Arts. Though his talent surpassed the age, he had no arrogant disposition;" },
  { zh: "善機巧，尤致思於天文、陰陽、歷算，作渾天儀，著《靈憲》。", literal: "skilled in ingenious devices, especially applying thought to astronomy, yin-yang, calendars and reckoning, made the armillary sphere, wrote Ling Xian.", idiomatic: "he was skilled in ingenious devices and especially applied thought to astronomy, yin-yang, and calendrical reckoning; he made the armillary sphere and wrote Ling Xian." },
  { zh: "性恬憺，不慕當世；", literal: "Nature tranquil and shallow, not admiring the present age;", idiomatic: "His nature was tranquil and unassuming; he did not court the present age;" },
  { zh: "所居之官輒積年不徙。", literal: "whatever office he held, for years he was not transferred.", idiomatic: "whatever office he held, for years he was not transferred." },
  { zh: "太尉寵參，在三公中最名忠直，數為左右所毀。", literal: "Grand Commandant Dou Chong, among the Three Excellencies most famed for loyalty and straightness, was repeatedly slandered by those at the left and right.", idiomatic: "Grand Commandant Dou Chong, among the Three Excellencies most famed for loyalty and straightness, was repeatedly slandered by those at the Emperor's side." },
  { zh: "會所舉用忤帝旨，司隸承風案之。", literal: "It happened that those he recommended and employed went against the Emperor's intent; the Director of the Secretariat followed the wind and investigated him.", idiomatic: "It happened that those he recommended went against the Emperor's intent; the Director of the Secretariat followed the wind and investigated him." },
  { zh: "時當會茂才、孝廉，參以被奏，稱疾不會。", literal: "At the time it was time to convene Outstanding Talents and Filial and Incorrupt—Chong because impeached claimed illness and did not attend.", idiomatic: "At the time it was time to convene Outstanding Talents and Filial and Incorrupt. Chong, because he had been impeached, claimed illness and did not attend." },
  { zh: "廣漢上計掾段恭因會上疏曰：「伏見道路行人、農夫、織婦皆曰：『太尉參竭忠盡節，徒以直道不能曲心，孤立群邪之間，自處中傷之地。", literal: "Duan Gong, reporting clerk of Guanghan at the annual accounting, took advantage to memorialize: \"I see travelers on the road, farmers, weaving women all say: 'Grand Commandant Chong exhausts loyalty and utmost integrity, only because the straight way cannot bend his heart, standing alone among the throng of evils, placing himself in the ground of injury.'\"", idiomatic: "Duan Gong, reporting clerk of Guanghan at the annual accounting, took advantage to memorialize, saying, \"I see travelers on the road, farmers, and weaving women all say, 'Grand Commandant Dou Chong exhausts loyalty and utmost integrity, only because the straight way cannot bend his heart. He stands alone among the throng of evils and places himself where he will be injured.'\"" },
  { zh: "』夫以讒佞傷毀忠正，此天地之大禁，人主之至誡也！", literal: "\" To use slanderous flatterers to injure and destroy the loyal and upright—this is the great prohibition of Heaven and Earth, the utmost warning of the lord!", idiomatic: "\" To use slanderous flatterers to injure and destroy the loyal and upright—this is the great prohibition of Heaven and Earth and the utmost warning for a lord!" },
  { zh: "昔白起賜死，諸侯酌酒相賀；", literal: "Formerly when Bai Qi was granted death, the feudal lords raised cups and toasted one another in congratulation;", idiomatic: "Formerly when Bai Qi was granted death, the feudal lords raised cups and toasted one another in congratulation;" },
  { zh: "季子來歸，魯人喜其紓難。", literal: "when Jizi returned, the men of Lu rejoiced that their difficulty was relieved.", idiomatic: "when Jizi returned, the men of Lu rejoiced that their difficulty was relieved." },
  { zh: "夫國以賢治，君以忠安。", literal: "The state is governed by the worthy, the lord is secured by the loyal.", idiomatic: "The state is governed by the worthy; the lord is secured by the loyal." },
  { zh: "今天下咸欣陛下有此忠賢，願卒寵任以安社稷。", literal: "Now all under heaven rejoice that Your Majesty has this loyal worthy—we wish you finally favor and entrust him to secure the altars of state.", idiomatic: "Now all under heaven rejoice that Your Majesty has this loyal worthy. We wish you finally to favor and entrust him to secure the altars of state." },
  { zh: "」書奏，詔即遣小黃門視參疾，太醫致羊酒。", literal: "\" The memorial was submitted; an edict immediately sent Junior Yellow Gate to visit Chong's illness, the imperial physician presented lamb and wine.", idiomatic: "\" The memorial was submitted. An edict immediately sent a Junior Yellow Gate to visit Chong's illness, and the imperial physician presented lamb and wine." },
  { zh: "後參夫人疾前妻子，投於井而殺之；", literal: "Later Chong's wife fell ill; his former wife—he threw her in a well and killed her;", idiomatic: "Later when Chong's wife fell ill, he threw his former wife into a well and killed her;" },
  { zh: "雒陽令祝良奏參罪。", literal: "Magistrate of Luoyang Zhu Liang memorialized Chong's crime.", idiomatic: "Magistrate of Luoyang Zhu Liang memorialized Chong's crime." },
  { zh: "秋，七月，己未，參竟以災異免。", literal: "In autumn, the seventh month, on jiwei day, Chong in the end was dismissed because of prodigies and anomalies.", idiomatic: "In autumn, in the seventh month, on jiwei day, Chong was in the end dismissed because of prodigies and anomalies." },
  { zh: "八月，己巳，以大鴻臚施延為太尉。", literal: "In the eighth month, on jisi day, made Minister Herald Shi Yan Grand Commandant.", idiomatic: "In the eighth month, on jisi day, Minister Herald Shi Yan was made Grand Commandant." },
  { zh: "鮮卑寇馬城，代郡太守擊之，不克。", literal: "The Xianbei raided Ma Castle; Administrator of Dai commandery struck them but did not overcome.", idiomatic: "The Xianbei raided Ma Castle. The Administrator of Dai commandery struck them but did not overcome them." },
  { zh: "頃之，其至鞬死。", literal: "Before long their chanyu died.", idiomatic: "Before long their chanyu died." },
  { zh: "鮮卑由是抄盜差稀。", literal: "The Xianbei thereby had raids and thefts comparatively rare.", idiomatic: "The Xianbei thereby raided and plundered somewhat less." },
  { zh: "category:資治通鑑", literal: "—", idiomatic: "—" }
];
